add(751, [
'''סנופ דוגי דוג, קלווין ברודוס, גדל בלונג ביץ׳ שבקליפורניה, והעולם הכיר אותו כמעט בכל השירים של The Chronic של דוקטור דרה (אלבום 717), שבו היה האורח הקבוע והכוכב העולה. כולם חיכו לאלבום שלו, ו־Doggystyle, שיצא בסוף 1993 והופק על ידי דרה, היה אלבום הבכורה הראשון בתולדות המצעד האמריקאי שנכנס ישר למקום הראשון. השם שלו, הכינוי שקיבל כבר בילדותו מאמו, הפך למותג מוכר בכל העולם.''',
'''הצליל הוא המשך ישיר של הג׳י־פאנק של דרה: קצבים איטיים ונינוחים, בס עמוק וחם, צלילי סינתיסייזר גבוהים ומייבבים, ודגימות של פאנק וסול משנות השבעים. אבל מה שהופך את האלבום למיוחד הוא הקול של סנופ: רגוע, רך, כמעט מתנמנם, עם זרימה חלקה ושובבה, שנשמעת כאילו אין לו שום מאמץ. Gin and Juice הוא שיר מסיבה קליל על ערב רגיל בשכונה, עם פזמון שכולם שרים. Who Am I (What's My Name)? הוא הצגה עצמית מצחיקה ובטוחה, ו־Doggy Dogg World הוא שיר נינוח עם להקת הסול הוותיקה הדרמטיקס. יש גם גרסה חדשה ל־La Di Da Di של סליק ריק. המילים בוטות מאוד, עם שפה גסה ורגעים קשים.''',
'''Doggystyle נמכר במיליוני עותקים, והפך את סנופ לאחד הראפרים המפורסמים בעולם. הוא קבע את הצליל של ההיפ הופ של החוף המערבי לשנים, והקול שלו נשאר מזוהה עד היום. סנופ המשיך לקריירה ארוכה במיוחד, גם כשחקן, כמגיש וכאיש עסקים, והפך לדמות מוכרת גם למי שלא שומע היפ הופ.''',
'''שמעו את Gin and Juice, ושימו לב כמה לאט ובנחת הוא שר. ואחר כך חזרו ל־The Chronic של דוקטור דרה (אלבום 717), ושמעו את סנופ הצעיר בפעם הראשונה.''',
], [
('Gin and Juice', 'שיר מסיבה קליל על ערב רגיל בשכונה, עם קול רך ופזמון שכולם שרים.'),
('Who Am I (What\'s My Name)?', 'הצגה עצמית מצחיקה ובטוחה, עם קצב פאנקי וקריאות שאי אפשר לשכוח.'),
('Doggy Dogg World', 'שיר נינוח וחם עם להקת הסול הוותיקה הדרמטיקס, כמו ערב קיץ ארוך.'),
])

add(752, [
'''לו בארלו היה הבסיסט של דיינוזור ג׳וניור (אלבומים 586 ו־625), עד שהמנהיג של הלהקה, ג׳יי מסקיס, סילק אותו בסוף שנות השמונים. עוד לפני כן הוא הקליט בבית, על רשמקול פשוט, שירים קטנים, שקטים וכנים, עם חברו אריק גפני, ומהם נולדה סבאדו. אחר כך הצטרף גם ג׳ייסון לוונשטיין, ושלושתם כתבו ושרו כל אחד את השירים שלו. Bubble and Scrape, שיצא ב־1993 בחברת התקליטים סאב פופ, הוא אלבום מגוון במיוחד, שבו שלושה כותבים שונים מאוד חולקים תקליט אחד.''',
'''הצליל מחוספס וביתי, מה שנקרא לו־פיי: גיטרות אקוסטיות וחשמליות, תופים פשוטים, הקלטה לא מלוטשת, ולפעמים רעש שמשתלט על הכל. השירים של בארלו הם הלב של האלבום: שירים רכים, עצובים ואישיים מאוד, על אהבה שנגמרת ועל פרידה, שנשמעים כמו יומן פתוח. Soul and Fire הוא שיר פרידה כואב ויפה, עם מנגינה פשוטה ופזמון חם. Happily Divided ו־Two Years Two Days עדינים ונוגים. השירים של גפני ולוונשטיין רועשים, מהירים ומשונים יותר, כמעט פאנק, ויוצרים ניגוד חד לשירים השקטים, כך שהאלבום מרגיש כמו מסיבה של שלושה חברים עם טעם שונה לגמרי.''',
'''סבאדו הייתה אחת הלהקות החשובות של הלו־פיי האמריקאי, והשפיעה על להקות רבות שהקליטו בבית, בלי כסף ובלי אולפן. בארלו המשיך גם בפרויקטים אחרים, כמו הפולק אימפלוז׳ן, ובסוף אף חזר לנגן עם דיינוזור ג׳וניור, אחרי שנים של נתק.''',
'''שמעו את Soul and Fire בשקט, ואחריו את Bug של דיינוזור ג׳וניור (אלבום 625), ותשמעו את שני הצדדים של אותו בסיסט: הרעש של הלהקה הגדולה, והלב החשוף של השירים שלו.''',
], [
('Soul and Fire', 'שיר פרידה כואב ויפה של לו בארלו, עם מנגינה פשוטה ופזמון חם.'),
('Happily Divided', 'שיר עדין ונוגה על זוג שנפרד, בקול שקט וגיטרה רכה.'),
('Two Years Two Days', 'שיר קטן וכן על זמן שעובר ועל געגוע, כמו מכתב אישי.'),
])

add(753, [
'''הבו רדליז קמו בוואלסי, ליד ליברפול, בסוף שנות השמונים, ושמם לקוח מדמות מסתורית בספר "אל תיגע בזמיר". הכותב והגיטריסט מרטין קאר היה המוח של הלהקה, והזמר סייס נתן לשירים קול רך וחלומי. הם התחילו כלהקת שוגייז רועשת בחברת קריישן, אבל קאר רצה הרבה יותר. Giant Steps, שיצא ב־1993, קרוי על שם אלבום ג׳אז מפורסם של ג׳ון קולטריין, והוא אלבום ארוך, שאפתני ומלא הפתעות, שמנסה לחבר את כל המוזיקה שהלהקה אהבה.''',
'''בתוך האלבום יש כמעט הכל: גיטרות רועשות ומעוותות, פופ מתוק בסגנון הביטלס, דאב ורגאיי עם בס עמוק, כלי נשיפה, כלי מיתר, פסנתר, ורגעים ניסיוניים ומוזרים. שיר יכול להתחיל כבלדה רכה ולהפוך לחומה של רעש, או להיפך. Lazarus, אחד השירים המפורסמים שלהם, נפתח בבס איטי של דאב ובחצוצרה, ומתפוצץ לפזמון ענק ושמח. Wish I Was Skinny הוא שיר פופ קצר ומתוק, ו־I Hang Suspended קצבי ומרחף. Barney (...and Me) קליט ושמח, עם כלי נשיפה, ו־Leaves and Sand נוגה ויפה.''',
'''Giant Steps זכה לשבחים רבים, ומבקרים בבריטניה בחרו בו לאחד מאלבומי השנה. ההצלחה המסחרית הגדולה הגיעה רק שנתיים אחר כך, עם השיר השמח Wake Up Boo!, אבל רבים רואים ב־Giant Steps את היצירה הטובה ביותר שלהם, ואחד האוצרות הנשכחים של התקופה. קאר המשיך לכתוב שירים גם אחרי שהלהקה התפרקה, וסייס הוציא אלבומים משלו, אבל Giant Steps נשאר הרגע שבו הכל התחבר.''',
'''זה אלבום ארוך ומגוון, ואין צורך לשמוע אותו בבת אחת. התחילו מ־Lazarus, ושימו לב לרגע שבו הדאב השקט הופך לפזמון. ואחר כך נסו את Revolver של הביטלס (אלבום 60).''',
], [
('Lazarus', 'נפתח בבס איטי של דאב ובחצוצרה, ומתפוצץ לפזמון ענק, שמח ומשחרר.'),
('Wish I Was Skinny', 'שיר פופ קצר ומתוק, עם מנגינה בסגנון הביטלס וגיטרות רכות.'),
('I Hang Suspended', 'שיר קצבי ומרחף, עם גיטרות מזמזמות וקול רך וחלומי.'),
])

add(755, [
'''מת׳וד מן היה הראשון מחברי הוו־טאנג קלאן שהוציא אלבום סולו, אחרי ההצלחה של Enter the Wu-Tang (אלבום 748), שבו היה לו גם שיר שנקרא על שמו. החוזה המיוחד של הקבוצה אפשר לכל חבר לחתום בחברה אחרת, והוא חתם בדף ג׳אם, אחת מחברות ההיפ הופ החשובות. Tical, שיצא בסוף 1994, הופק כולו על ידי RZA, המפיק והמוח של הקבוצה, והשם שלו הוא אחד מהכינויים הרבים שהיו למת׳וד מן עצמו.''',
'''הצליל של Tical אפל, עכור וכבד עוד יותר מזה של אלבום הקבוצה: קצבים איטיים ומאובקים, בס עמוק, דגימות קודרות ומעוותות, ותחושה של רחוב בלילה גשום. מעל כל זה עומד הקול של מת׳וד מן, מחוספס, צרוד, שובב ומלא כריזמה, עם זרימה גמישה וקלה, שהפכה אותו לאחד הראפרים האהובים של התקופה. Bring the Pain הוא הלהיט הגדול, שיר מאיים ומקפץ עם פזמון קצר ובלתי נשכח. All I Need הוא שיר אהבה, דבר נדיר באלבום קשוח כזה, ו־Release Yo' Delf בנוי על השיר המפורסם I Will Survive של גלוריה גיינור, עם שירה של זמרת גוספל. Meth vs. Chef הוא קרב ראפ עם חברו ראקוון.''',
'''גרסה אחרת של All I Need, עם הזמרת מרי ג׳יי בלייג׳, זכתה אחר כך בפרס גראמי, ומת׳וד מן הפך לכוכב גם מחוץ לעולם ההיפ הופ, כשחקן בסרטים ובסדרות. Tical פתח את הדרך לגל של אלבומי סולו של חברי הקבוצה, שרבים מהם נחשבים לקלאסיקות.''',
'''שמעו את Bring the Pain, ושימו לב לצליל העכור של הקצב. ואחר כך שמעו את Method Man מתוך Enter the Wu-Tang (אלבום 748), כדי להכיר אותו בפעם הראשונה.''',
], [
('Bring the Pain', 'הלהיט הגדול, קצב מאיים ומקפץ, קול צרוד ופזמון קצר ובלתי נשכח.'),
('All I Need', 'שיר אהבה נדיר באלבום קשוח, על אישה שעומדת לצידו בכל מצב.'),
('Release Yo\' Delf', 'בנוי על I Will Survive של גלוריה גיינור, עם שירה של זמרת גוספל.'),
])

add(756, [
'''פרנק בלאק הוא השם החדש של בלאק פרנסיס, הזמר, הגיטריסט וכותב השירים של הפיקסיז (אלבומים 623, 655 ו־669). בתחילת 1993 הוא פירק את הלהקה, בהודעה קצרה ברדיו, ובלי לספר קודם לרוב חבריו, והתחיל קריירת סולו. Teenager of the Year, אלבום הסולו השני שלו, יצא ב־1994, והוא ארוך ושופע במיוחד: עשרים ושניים שירים, יותר משעה של מוזיקה. את רובו הפיק יחד עם הקלידן אריק דרו פלדמן, שניגן קודם עם קפטן ביפהארט.''',
'''המוזיקה מגוונת מאוד: רוק אלטרנטיבי רועש בסגנון הפיקסיז, פופ מתוק של שנות השישים, קאנטרי, רוקנרול ישן, ואפילו רגאיי ופאנק. בלאק שר על דברים מוזרים ומצחיקים: על חלל, על מכוניות, על משחקי מחשב ישנים, על היסטוריה ועל חלומות על עולמות אחרים. Headache הוא שיר פופ רוק מושלם, קליט וחם, עם פזמון גדול. Whatever Happened to Pong? הוא שיר פאנק קצר ומהיר, שמתגעגע למשחק המחשב הראשון. Speedy Marie הוא שיר אהבה רך ויפה, ו־(I Want to Live on an) Abstract Plain רועש וצועק, כמו בימי הפיקסיז. Los Angeles מהיר ואנרגטי, עם גיטרות רועשות.''',
'''Teenager of the Year לא נמכר כמו אלבומי הפיקסיז, אבל רבים רואים בו את אלבום הסולו הטוב ביותר של בלאק, ואוצר של שירים נהדרים שמחכים לגילוי. כעבור שנים הפיקסיז התאחדו מחדש, והמשיכו להופיע ולהוציא אלבומים, אבל בלאק המשיך במקביל גם בקריירת הסולו שלו.''',
'''זה אלבום ארוך, אז אין צורך לשמוע אותו בבת אחת. התחילו מ־Headache, ואחריו שמעו את Here Comes Your Man מתוך Doolittle (אלבום 655), שני שירי פופ מושלמים מאותו כותב.''',
], [
('Headache', 'שיר פופ רוק מושלם, קליט וחם, עם גיטרות מצלצלות ופזמון גדול.'),
('Whatever Happened to Pong?', 'שיר פאנק קצר ומהיר, שמתגעגע בהומור למשחק המחשב הראשון בעולם.'),
('Speedy Marie', 'שיר אהבה רך ויפה, עם מנגינה פשוטה וקול חם ושקט.'),
])

add(757, [
'''גירלס אגיינסט בויז קמו בוושינגטון הבירה בסוף שנות השמונים, מתוך סצנת הפאנק וההארדקור של העיר, אותה סצנה שממנה יצאו פוגאזי (אלבום 657). הלהקה הייתה מיוחדת בהרכב שלה: שני בסיסטים, אלי ג׳אני, שניגן גם בקלידים ובדגימות, וג׳וני טמפל, לצד הזמר והגיטריסט סקוט מקלאוד והמתופף אלקסיס פלייסיג. Venus Luxure No. 1 Baby, האלבום השני שלהם, יצא ב־1993 בחברת התקליטים העצמאית טאץ׳ אנד גו משיקגו.''',
'''הצליל כבד, אפל וחושני: שני הבסים יוצרים קיר עבה ועמוק, הגיטרה חדה וצורמת, התופים חזקים ומדויקים, והקלידים והדגימות מוסיפים צלילים מוזרים ומאיימים. סקוט מקלאוד שר בקול נמוך, צרוד ולוחש, כמו מישהו שמדבר אליכם בבר אפל בשעה מאוחרת בלילה. המוזיקה מקפצת וגרובית, כמעט כמו מוזיקת ריקודים, אבל נשארת רועשת וכועסת. In Like Flynn הוא שיר מאיים וחושני, עם בס עמוק וקצב מהפנט. Go Be Delighted מהיר ומלא אנרגיה, ו־Bullet Proof Cupid חד וקצבי, עם פזמון שקל לזכור. Satin Down איטי וכבד, עם אווירה של לילה מאוחר. ההקלטה כבדה וקרובה, כאילו הלהקה מנגנת ממש בתוך החדר שלכם.''',
'''הלהקה מעולם לא הפכה לפופולרית מאוד, אבל השפיעה על להקות רבות של רוק אלטרנטיבי, שחיברו רעש של פאנק עם גרוב ואווירה של לילה. Venus Luxure No. 1 Baby נחשב לאלבום הטוב ביותר שלה, ואחד האלבומים המרשימים של סצנת הרוק העצמאי האמריקאי בתחילת שנות התשעים.''',
'''שמעו את In Like Flynn באוזניות, ושימו לב לשני הבסים שמנגנים יחד. ואחר כך שמעו את Repeater של פוגאזי (אלבום 657), מאותה עיר ומאותה סצנה.''',
], [
('In Like Flynn', 'שיר מאיים וחושני, עם שני בסים עמוקים, קול לוחש וקצב מהפנט.'),
('Bullet Proof Cupid', 'שיר חד וקצבי, עם גיטרה צורמת ופזמון קצר שקל לזכור.'),
('Go Be Delighted', 'שיר מהיר ומלא אנרגיה, עם בס עבה ותופים חזקים ומדויקים.'),
])

add(758, [
'''ג׳רו דה דמג׳ה, קנדריק ג׳רואן דייוויס, גדל בברוקלין, והתפרסם בזכות הופעות אורח עם גאנג סטאר, הצמד של הראפר גורו והמפיק די ג׳יי פרימייר (אלבום 689). The Sun Rises in the East, אלבום הבכורה שלו, יצא ב־1994, והופק כולו על ידי פרימייר, אחד המפיקים הגדולים בתולדות ההיפ הופ. השם, "השמש עולה במזרח", מתייחס גם לברוקלין, שנמצאת במזרח ניו יורק, וגם לרעיונות רוחניים של התחדשות ושל הארה, שג׳רו עסק בהם הרבה.''',
'''הצליל מינימלי, יבש וחכם: קצבי תופים כבדים ופשוטים, דגימות קטנות ומוזרות של ג׳אז ושל פסנתר, וסקרצ׳ים מדויקים של פרימייר. בלי הרבה קישוטים, הכל נשען על הקצב ועל הקול. ג׳רו מדבר בקול עמוק ושקט, ומילותיו עוסקות באמונה, בחשיבה עצמאית, בביקורת על הגנגסטה ראפ, על אלימות ועל החומרנות שהשתלטה על ההיפ הופ. Come Clean, הסינגל הראשון, נבנה סביב צליל של טיפות מים, והוא אחד הקצבים המפורסמים של פרימייר. You Can't Stop the Prophet הוא סיפור מצחיק על נביא שנלחם בנבלים שנקראים קנאה ובורות. D. Original מהיר ובטוח בעצמו. פרימייר לא ממלא כאן את הקצבים בצלילים מיותרים, וכל דגימה קטנה מקבלת מקום לנשום.''',
'''האלבום לא נמכר בכמויות גדולות, אבל נחשב היום לאחת הקלאסיקות של ההיפ הופ של ניו יורק באמצע שנות התשעים, ולאחת העבודות הטובות של פרימייר. הוא הראה שאפשר לעשות היפ הופ קשה ומחוספס, עם מסר רוחני ומחשבתי.''',
'''שמעו את Come Clean, ושימו לב לטיפות המים בקצב. ואחר כך שמעו את Step in the Arena של גאנג סטאר (אלבום 689), כדי לשמוע את פרימייר כמה שנים קודם.''',
], [
('Come Clean', 'הסינגל הראשון, נבנה סביב צליל של טיפות מים, אחד הקצבים המפורסמים של פרימייר.'),
('You Can\'t Stop the Prophet', 'סיפור מצחיק על נביא שנלחם בנבלים בשם קנאה ובורות.'),
('D. Original', 'שיר מהיר ובטוח בעצמו, עם סקרצ׳ים חדים וקצב יבש וכבד.'),
])

add(759, [
'''אחרי ההצלחה של Slanted and Enchanted (אלבום 707), פייבמנט נפרדו מהמתופף התמהוני גארי יאנג, שהתנהגותו על הבמה הפכה לבעיה, ובמקומו הגיע סטיב ווסט. הלהקה הקליטה את האלבום הבא בניו יורק, וב־Crooked Rain, Crooked Rain, שיצא ב־1994, הצליל שלה הפך נקי, חם ומלודי יותר, בלי לאבד את ההומור ואת המוזרות. סטיבן מלקמוס כתב כאן כמה מהשירים היפים והקליטים ביותר שלו, ופייבמנט התקרבו לרגע לפופולריות של ממש.''',
'''הגיטרות עדיין רופפות ומלוכלכות, אבל המנגינות ברורות יותר, והאווירה רגועה ושמשית, כמו נסיעה במכונית בקליפורניה. מלקמוס שר בקול עצל ומשועשע, ומדבר על מוזיקה, על תהילה, על הלהקות של זמנו ועל ההתבגרות. Cut Your Hair, הלהיט הגדול, הוא שיר מצחיק על להקות שחושבות יותר על הדימוי מאשר על המוזיקה, עם "או או או" שכולם זוכרים. Gold Soundz הוא שיר נוסטלגי ויפה, אחד השירים האהובים של שנות התשעים. Range Life הוא שיר קאנטרי רגוע שבו מלקמוס לועג בעדינות ללהקות גדולות של אותם ימים, כמו הסמאשינג פאמפקינס. 5-4=Unity הוא קטע ג׳אז קטן ומשונה, מחווה ל־Take Five של דייב ברובק. Silence Kid ו־Stop Breathin רועשים ונוגים.''',
'''Crooked Rain, Crooked Rain היה האלבום המצליח ביותר של פייבמנט, והוא נחשב לאחד האלבומים החשובים של האינדי רוק האמריקאי. הוא הראה שאפשר לכתוב שירי פופ נהדרים ולהישאר מוזרים, עצמאיים ומחוץ למיינסטרים. Cut Your Hair אפילו הושמע הרבה ב־MTV, הישג נדיר ללהקה כזאת.''',
'''שמעו את Gold Soundz ואת Range Life ביום שמש. ואחר כך שמעו את Time Out של דייב ברובק (אלבום 23), ותשמעו את המקור ל־5-4=Unity.''',
], [
('Gold Soundz', 'שיר נוסטלגי ויפה, עם גיטרות רכות ומנגינה חמה, אחד האהובים של העשור.'),
('Cut Your Hair', 'הלהיט, שיר מצחיק על להקות שעסוקות בדימוי, עם "או או או" שכולם זוכרים.'),
('Range Life', 'שיר קאנטרי רגוע, שבו מלקמוס לועג בעדינות ללהקות הגדולות של זמנו.'),
])

add(760, [
'''פורטיסהד נולדו בבריסטול, אותה עיר שבה נולדו מסיב אטאק (אלבום 703), ונקראים על שם עיירה קטנה ליד העיר. ג׳ף בארו, מפיק צעיר שעבד בעבר כעוזר באולפן שבו הוקלט Blue Lines, פגש את הזמרת בת גיבונס, וצירף אליהם את הגיטריסט אדריאן אטלי. Dummy, אלבום הבכורה שלהם, יצא ב־1994, ומיד הפך לאחד האלבומים החשובים של התקופה. הם נמנעו כמעט לגמרי מראיונות ומהופעות בתקשורת, והמסתורין רק הגדיל את הקסם.''',
'''המוזיקה איטית, קודרת ויפה: קצבים איטיים של היפ הופ, סקרצ׳ים של תקליטים, בס עמוק, דגימות מפסקולים של סרטי ריגול ומתח משנות השישים, גיטרות מהדהדות וצלילים שנשמעים כמו מדע בדיוני ישן. ומעל כל זה עומד הקול של בת גיבונס, שביר, עצוב ומלא כאב, שנשמע כמו זמרת ג׳אז ישנה שאיבדה הכל. Sour Times נבנה על דגימה מתוך פסקול של לאלו שיפרין, והוא שיר אהבה מר ומהפנט. Glory Box, הסוגר, נבנה על דגימה מתוך שיר של אייזק הייז, ובו גיבונס שרה שהיא רוצה להיות אישה. Roads הוא אחד השירים העצובים והיפים של שנות התשעים, עם כלי מיתר שקטים. Numb ו־Wandering Star איטיים ומאיימים.''',
'''Dummy זכה בפרס מרקורי של 1995, ונמכר במיליוני עותקים. יחד עם מסיב אטאק וטריקי, פורטיסהד הפכו את בריסטול לבירת הטריפ הופ, והשפיעו על מוזיקה אלקטרונית, היפ הופ ופופ במשך עשרות שנים.''',
'''זה אלבום ללילה, בשקט ובחושך. שמעו את Roads באוזניות, ושימו לב לקול של גיבונס. ואחר כך שמעו את Hot Buttered Soul של אייזק הייז (אלבום 164), כדי להכיר את עולם הצלילים שממנו לקחו.''',
], [
('Glory Box', 'הסוגר, דגימה של אייזק הייז, וגיבונס שרה בכאב שהיא רוצה להיות אישה.'),
('Sour Times', 'שיר אהבה מר ומהפנט, שנבנה על דגימה מתוך פסקול של סרט ריגול ישן.'),
('Roads', 'אחד השירים העצובים והיפים של העשור, עם כלי מיתר שקטים וקול שבור.'),
])

add(761, [
'''אנדרו ות׳רול היה אחד התקליטנים והמפיקים החשובים של בריטניה בתחילת שנות התשעים: הוא זה שהפך שיר של פריימל סקרים ל־Loaded, והפיק את רוב Screamadelica (אלבום 704). בשנת 1993 הקים להקה משלו, הסייברס אוף פרדייס, יחד עם שני מפיקים צעירים, ג׳אגז קונר וגארי ברנס, וגם מועדון לילה וחברת תקליטים באותו שם. Haunted Dancehall, האלבום השני שלהם, יצא ב־1994, והוא בנוי כמו פסקול לסרט שלא קיים, על לונדון בלילה, על רחובות, שווקים ושכונות.''',
'''המוזיקה מחברת בין טכנו, דאב, היפ הופ איטי, ג׳אז ומוזיקת סרטים: בס עמוק ורך, קצבים איטיים ומתנדנדים, צלילי סינתיסייזר אפלים, הדהודים ארוכים של דאב, ודגימות קטנות שנשמעות כמו קולות מהרחוב. אין כאן כמעט שירה, והקטעים זורמים זה לתוך זה כמו סצנות בסרט. שיר הנושא, Haunted Dancehall, איטי, מסתורי ומאיים, כמו כניסה לאולם ריקודים נטוש בלילה. Wilmot קופצני ושמח יותר, עם קצב מתנדנד וצליל של להקה ישנה. Duke of Earlsfield, שנקרא על שם שכונה בדרום לונדון, ו־Flight Path Estate מתוחים ואפלים. Jacob Street 7am ו־Chapel Street Market 9am רכים ושקטים, כמו בוקר בעיר אחרי לילה ארוך. זה אלבום שמתאים במיוחד להאזנה באוזניות, כי יש בו המון פרטים קטנים שמתגלים בכל פעם מחדש.''',
'''Haunted Dancehall נחשב לאחד האלבומים היפים והמוזרים של המוזיקה האלקטרונית הבריטית של התקופה. ות׳רול המשיך ליצור ולתקלט עד מותו ב־2020, והשפיע על דורות של מוזיקאים, שראו בו גשר בין רוק, דאב ומוזיקת מסיבות.''',
'''שמעו את האלבום ברצף, בלילה, כמו פסקול לנסיעה בעיר. ואחר כך שמעו את Screamadelica (אלבום 704), ותשמעו את הצד השמח והשמשי של אותו מפיק.''',
], [
('Haunted Dancehall', 'שיר הנושא, איטי, מסתורי ומאיים, כמו כניסה לאולם ריקודים נטוש בלילה.'),
('Wilmot', 'קטע קופצני ושמח, עם קצב מתנדנד וצליל של להקה ישנה בשעת חגיגה.'),
('Duke of Earlsfield', 'קטע מתוח ואפל, קרוי על שם שכונה בדרום לונדון, עם בס עמוק.'),
])

add(762, [
'''נאס, נאסיר ג׳ונס, גדל בקווינסברידג׳, שכונת דיור ציבורי ענקית בקווינס שבניו יורק, ועזב את בית הספר כבר בכיתה ח׳. אביו, אולו דרה, היה מוזיקאי ג׳אז, ונאס גדל בבית מלא תקליטים וספרים. כשהיה בן עשרים בלבד הוציא את Illmatic, ב־1994, אחרי שנים שבהן כבר דיברו עליו בתעשייה כעל כישרון יוצא דופן. לאלבום הוא גייס את המפיקים הטובים ביותר של ניו יורק: די ג׳יי פרימייר, לארג׳ פרופסור, פיט רוק, קיו־טיפ מא טרייב קולד קווסט, ואל.אי.אס.''',
'''האלבום קצר, עשרה שירים בלבד, כארבעים דקות, ואין בו אף שיר מיותר. הקצבים חמים ועשירים, עם דגימות של ג׳אז, סול ופאנק, ובתוכם נאס מספר על החיים בשכונה בדיוק, בשפה עשירה ובתמונות חדות, כמו סופר או משורר. N.Y. State of Mind, עם קצב של פרימייר ופסנתר אפל, הוא תיאור חי ומפחיד של רחובות הלילה. The World Is Yours, שהפיק פיט רוק, הוא שיר אופטימי על חלומות ועל אפשרויות, למרות הכל. Life's a Bitch, עם הראפר הצעיר איי־זי, מסתיים בסולו של קורנט שמנגן אביו של נאס. It Ain't Hard to Tell משתמש בדגימה מתוך Human Nature של מייקל ג׳קסון.''',
'''Illmatic נחשב לאחד מאלבומי ההיפ הופ הטובים בכל הזמנים, ולאבן דרך בכתיבת ראפ. הוא לא נמכר מיד בכמויות גדולות, אבל השפעתו עצומה, ורבים מהראפרים הגדולים שבאו אחריו רואים בו מודל ליצירה.''',
'''הקשיבו למילים, והתחילו מ־N.Y. State of Mind. ואחר כך שמעו את Human Nature מתוך Thriller של מייקל ג׳קסון (אלבום 507), ותשמעו את המקור לדגימה.''',
], [
('N.Y. State of Mind', 'תיאור חי ומפחיד של רחובות הלילה, עם פסנתר אפל וקצב של פרימייר.'),
('The World Is Yours', 'שיר אופטימי על חלומות ואפשרויות, עם פסנתר חם של פיט רוק.'),
('Life\'s a Bitch', 'שיר עם איי־זי, שמסתיים בסולו קורנט של אביו של נאס.'),
])

add(763, [
'''הביסטי בויז התחילו כשלישיית ראפ פרועה ומצחיקה עם Licensed to Ill (אלבום 566), והפכו לאמנים מתוחכמים עם Paul's Boutique (אלבום 643). בתחילת שנות התשעים הם חזרו לנגן בעצמם בכלים, כמו בימי נעוריהם כלהקת פאנק, ובנו אולפן משלהם בלוס אנג׳לס. Ill Communication, שיצא ב־1994, הוא המשך לכיוון הזה: אלבום שמחבר ראפ, פאנק, ג׳אז, הארדקור וקטעי כלי מאולתרים, עם הקלידן מאני מארק שמנגן איתם. הוא הגיע למקום הראשון במצעד האמריקאי.''',
'''האלבום מגוון ומפתיע, וכמעט כל שיר שונה מקודמו. Sabotage הוא שיר רוק רועש ומטורף, עם בס מעוות, צעקות ותופים מתפרצים, והקליפ שלו, פרודיה על סדרות שוטרים משנות השבעים בבימוי ספייק ג׳ונז, הפך לאחד הקליפים המפורסמים בתולדות MTV. Sure Shot הפותח נבנה על דגימה של חליל ג׳אז, ובו אדם יאוק שר בית שלם של כבוד לנשים, צעד חשוב ללהקה שהתחילה עם שירים גסים ושוביניסטיים. Root Down ו־Get It Together, עם קיו־טיפ מא טרייב קולד קווסט, הם ראפ חם ונינוח. יש גם קטעי פאנק הארדקור קצרים ומהירים, וקטעי פאנק וג׳אז אינסטרומנטליים, כמו Sabrosa. Bodhisattva Vow עוסק באמונה הבודהיסטית של יאוק.''',
'''Ill Communication היה אחד האלבומים החשובים של הביסטי בויז, והוכיח שהם מסוגלים לגדול ולהשתנות. השלושה הפכו גם לפעילים למען עצמאות טיבט, וארגנו קונצרטים גדולים למענה. אדם יאוק מת ב־2012, והלהקה הפסיקה להופיע.''',
'''שמעו את Sabotage בווליום גבוה, ואחריו את Sure Shot, ותשמעו את שני הצדדים של הלהקה. ואחר כך חזרו ל־Licensed to Ill (אלבום 566), ושימו לב כמה הם השתנו.''',
], [
('Sabotage', 'שיר רוק רועש ומטורף, בס מעוות וצעקות, עם אחד הקליפים המפורסמים בעולם.'),
('Sure Shot', 'הפותח, דגימה של חליל ג׳אז, ובית שלם של כבוד לנשים מפי אדם יאוק.'),
('Get It Together', 'ראפ חם ונינוח עם קיו־טיפ, קצב איטי וחילופי שורות מצחיקים.'),
])

add(764, [
'''אלביס קוסטלו הוא אחד מכותבי השירים החשובים של בריטניה, וכבר פגשנו אותו באלבומים רבים, מ־My Aim Is True (אלבום 390) ועד Blood & Chocolate (אלבום 564). בשנים שאחרי האחרון הוא נפרד מלהקת האטרקשנס, הקליט אלבומים עם מוזיקאים אחרים, ואף עבד עם רביעיית כלי מיתר קלאסית. ב־Brutal Youth, שיצא ב־1994, הוא חזר לרוק, ולצידו שוב ניגנו חברי האטרקשנס, הקלידן סטיב ניב, הבסיסט ברוס תומאס והמתופף פיט תומאס. בכמה שירים ניגן בבס גם ניק לואו, שהפיק את אלבומיו הראשונים.''',
'''הצליל מזכיר את ימי הזוהר של קוסטלו בסוף שנות השבעים: גיטרות חדות, אורגן מתפתל, תופים חזקים, ושירים מהירים ומלאי אנרגיה. אבל הכתיבה בוגרת יותר, והמילים מרות ושנונות מתמיד, על אהבה, על בגידה, על זקנה ועל עולם אכזרי. Pony St. הפותח מהיר ועוקצני, על אם ובתה המתבגרת. 13 Steps Lead Down הוא שיר רוק קצבי וסוחף, עם פזמון גדול. Sulky Girl הוא שיר נוגה ודרמטי, עם פסנתר, ו־You Tripped at Every Step הוא בלדה יפה ועצובה. This Is Hell מציג גיהינום מצחיק, שבו מושמעים לנצח שירים אהובים. Kinder Murder אפל וכועס.''',
'''Brutal Youth זכה לביקורות טובות, ונחשב לאחד האלבומים החזקים של קוסטלו מתקופה זו. אחריו המשיך קוסטלו לחקור סגנונות רבים, ועבד עם אמנים כמו ברט בכרך, אן סופי פון אוטר והרוטס, ונשאר אחד היוצרים הסקרנים והפוריים של המוזיקה הבריטית.''',
'''שמעו את 13 Steps Lead Down ואחריו את This Year's Model (אלבום 400), ותשמעו כמה מעט הלהקה השתנתה בששה עשר שנים, וכמה השתנה הכותב.''',
], [
('13 Steps Lead Down', 'שיר רוק קצבי וסוחף, עם גיטרות חדות, אורגן ופזמון גדול.'),
('Sulky Girl', 'שיר נוגה ודרמטי, עם פסנתר ומנגינה מתרוממת על בחורה זועפת.'),
('You Tripped at Every Step', 'בלדה יפה ועצובה, עם קול רך ומלודיה חמה של פעם.'),
])

add(765, [
'''אחרי Your Arsenal (אלבום 711), השנים של מוריסי היו קשות: כמה מהאנשים הקרובים אליו מתו בזה אחר זה, בהם המפיק מיק רונסון, המנהל שלו ובמאי הקליפים שעבד איתו שנים. Vauxhall and I, שיצא ב־1994 והופק על ידי סטיב לילייוויט, מושפע מהאבל הזה. הוא שקט, רך ומהורהר יותר מקודמו, ורבים, כולל מוריסי עצמו, רואים בו את אלבום הסולו הטוב ביותר שלו. הוא הגיע למקום הראשון במצעד הבריטי.''',
'''הלהקה של Your Arsenal חזרה, עם הגיטריסטים אלן ווייט ובוז בורר, אבל הצליל עדין ומעודן יותר: גיטרות מנצנצות ורכות, מעט כלי מיתר, והקול של מוריסי, חם, עצוב ומלא חמלה, אולי היפה ביותר שלו. השירים עוסקים בחברות, בבדידות, באובדן ובאהבה, עם הומור עדין. Now My Heart Is Full הפותח הוא שיר מרגש וגדול, שבו מוריסי מזכיר דמויות מספר של גרהם גרין, ומרגיש סוף סוף שליבו מלא. The More You Ignore Me, the Closer I Get, הלהיט הגדול, הוא שיר שובב ומצחיק על אהבה עקשנית. Hold On to Your Friends הוא שיר רך ומנחם על חשיבות החברים. Speedway, הסוגר, דרמטי ועוצמתי, ונפתח בצליל של מסור חשמלי. Billy Budd מהיר וקופצני.''',
'''Vauxhall and I נחשב היום לאחד האלבומים היפים של מוריסי, ומראה צד בוגר ושקט שלו, רחוק מהמריבות ומהפרובוקציות שבהן נודע. הוא המשיך להוציא אלבומים במשך עשורים, ולהיות דמות מסקרנת ושנויה במחלוקת.''',
'''שמעו את Now My Heart Is Full בשקט, ואחריו את There Is a Light That Never Goes Out מתוך The Queen Is Dead (אלבום 583), שני שירים גדולים מאותו קול, בהפרש של שמונה שנים.''',
], [
('Now My Heart Is Full', 'הפותח, שיר מרגש וגדול על לב שסוף סוף מתמלא, עם גיטרות מנצנצות.'),
('The More You Ignore Me, the Closer I Get', 'הלהיט, שיר שובב ומצחיק על אהבה עקשנית שלא מוותרת.'),
('Hold On to Your Friends', 'שיר רך ומנחם על חשיבות החברים, בקול חם ושקט.'),
])

add(766, [
'''טי־אל־סי היו שלישיית זמרות מאטלנטה: טי־בוז, טיון ווטקינס, עם קול עמוק ונמוך, צ׳ילי, רוזונדה תומאס, עם קול רך ומתוק, ולפט איי, ליסה לופז, הראפרית הפרועה והיצירתית של הקבוצה. אחרי אלבום בכורה צבעוני ומצליח, הן הוציאו ב־1994 את CrazySexyCool, שהשם שלו מתאר את שלוש האישיויות שלהן. את השירים הפיקו כמה מהמפיקים הגדולים של התקופה, ביניהם דאלאס אוסטין, בייביפייס, ואורגנייזד נויז מאטלנטה.''',
'''המוזיקה היא אר אנד בי והיפ הופ חושני ובוגר: קצבים איטיים וחלקים, בס עמוק, כלי נשיפה, גיטרות רכות, והרמוניות קוליות חמות. השירים עוסקים באהבה, במיניות, בעצמאות של נשים, אבל גם בנושאים קשים. Waterfalls, הלהיט הגדול, הוא שיר שקט ונוגה שמזהיר מפני סכנות של הרחוב ושל מחלות, עם פזמון מפורסם ובית של לפט איי. Creep הוא שיר חושני על אישה שבוגדת בבן זוגה הבוגד, עם חצוצרה רכה. Red Light Special, שכתב בייביפייס, הוא בלדה איטית ומפתה. Diggin' on You קליל ושמח, כמו יום קיץ בפארק. שלוש הזמרות משלימות זו את זו: הקול העמוק של טי־בוז, המתיקות של צ׳ילי והראפ השובב של לפט איי.''',
'''CrazySexyCool נמכר ביותר מעשרה מיליון עותקים בארצות הברית, והפך את טי־אל־סי לאחת מקבוצות הבנות המצליחות בתולדות המוזיקה. הוא זכה בפרסי גראמי, והשפיע על דור שלם של זמרות אר אנד בי. לפט איי נהרגה בתאונת דרכים ב־2002, וטי־בוז וצ׳ילי ממשיכות להופיע יחד.''',
'''שמעו את Waterfalls, ושימו לב למילים, מאחורי המנגינה הרכה. ואחר כך שמעו את Rhythm Nation 1814 של ג׳נט ג׳קסון (אלבום 660), עוד אלבום אר אנד בי עם מסר.''',
], [
('Waterfalls', 'הלהיט, שיר שקט ונוגה שמזהיר מפני סכנות הרחוב, עם פזמון מפורסם.'),
('Creep', 'שיר חושני על אישה שמשלמת לבן זוגה הבוגד, עם חצוצרה רכה.'),
('Red Light Special', 'בלדה איטית ומפתה שכתב בייביפייס, עם הרמוניות חמות וקצב רך.'),
])

add(767, [
'''אואזיס קמו במנצ׳סטר בתחילת שנות התשעים, סביב שני אחים שלא הפסיקו לריב: ליאם גלאגר, הזמר עם הקול המחוספס והיהיר, ונואל גלאגר, הגיטריסט שכתב את כל השירים. אלן מגי, הבעלים של חברת התקליטים קריישן, ראה אותם במקרה מופיעים במועדון קטן בגלזגו ב־1993, והחתים אותם כמעט במקום. Definitely Maybe, אלבום הבכורה שלהם, יצא באוגוסט 1994, והיה אז אלבום הבכורה שנמכר הכי מהר בתולדות בריטניה. בתחילת הדרך הם הופיעו במועדונים קטנים במנצ׳סטר, ונואל עבד במקביל כטכנאי של להקה אחרת מהעיר, האינספירל קרפטס.''',
'''הצליל פשוט, חזק ובטוח בעצמו: שכבות עבות של גיטרות חשמליות, תופים ישירים, ופזמונים ענקיים שנכתבו כדי שאצטדיון שלם ישיר אותם. ההשפעות ברורות, מהביטלס ועד הסקס פיסטולס, ובשירים מורגשת אופטימיות של צעירים ממעמד הפועלים, שחולמים להפוך לכוכבים. Rock 'n' Roll Star הפותח הוא הצהרה גאה על החלום הזה. Live Forever הוא שיר יפה ומלא תקווה על הרצון לחיות לנצח, אחד השירים האהובים של שנות התשעים. Supersonic, הסינגל הראשון, איטי, כבד ומצחיק, עם מילים חסרות היגיון. Cigarettes & Alcohol נבנה על ריף שמזכיר את T. רקס, ו־Slide Away הוא שיר אהבה גדול ומתפרץ.''',
'''Definitely Maybe הפך את אואזיס לאחת הלהקות הגדולות בבריטניה, יחד עם בלר, היריבה שלהם. האלבום הבא, (What's the Story) Morning Glory?, הפך אותם לתופעה עולמית. האחים המשיכו לריב, הלהקה התפרקה ב־2009, וחזרה להופיע רק אחרי שנים רבות.''',
'''שמעו את Live Forever ואת Slide Away בווליום גבוה. ואחר כך שמעו את Electric Warrior של T. רקס (אלבום 238), ותשמעו את המקור לריף של Cigarettes & Alcohol.''',
], [
('Live Forever', 'שיר יפה ומלא תקווה על הרצון לחיות לנצח, אחד האהובים של העשור.'),
('Supersonic', 'הסינגל הראשון, איטי וכבד, עם מילים מצחיקות שאין בהן הרבה היגיון.'),
('Slide Away', 'שיר אהבה גדול ומתפרץ, עם גיטרות עבות וקול מחוספס ומלא רגש.'),
])

add(768, [
'''סאונדגרדן קמו בסיאטל עוד באמצע שנות השמונים, הרבה לפני שהגראנג׳ הפך לתופעה עולמית, והיו הלהקה הראשונה מהסצנה שחתמה בחברת תקליטים גדולה. במרכזה עמד כריס קורנל, זמר עם קול ענק, שיכול לעבור מלחישה לצעקה גבוהה ועוצמתית, לצד הגיטריסט קים תאיל, הבסיסט בן שפרד והמתופף מאט קמרון. Superunknown, שיצא ב־1994, היה האלבום הרביעי שלהם, והוא הגיע ישר למקום הראשון במצעד האמריקאי.''',
'''הצליל כבד ומטאלי, עם השפעות ברורות של בלאק סבאת׳, אבל גם מגוון ופסיכדלי, עם רגעים שמזכירים את הביטלס ומוזיקה הודית. הגיטרות מכוונות נמוך, המשקלים המוזיקליים מוזרים ולא שגרתיים, והשירים עוסקים בבדידות, בדיכאון, במוות ובניכור, בכנות קשה. Black Hole Sun, הלהיט הגדול, הוא שיר פסיכדלי, מוזר ויפה, עם גיטרה מסתחררת ופזמון ענק, והקליפ הסוריאליסטי שלו הפך למפורסם מאוד. Spoonman, שבו מנגן אמן רחוב מסיאטל בכפיות, קצבי ומשונה. Fell on Black Days הוא שיר איטי ומרגש על תקופה של עצב שמגיעה בלי סיבה. Head Down ו־Half משתמשים בצלילים הודיים, ו־The Day I Tried to Live קשה וכן.''',
'''Superunknown נמכר במיליוני עותקים, וזכה בשני פרסי גראמי. הוא נחשב לאחד האלבומים הגדולים של הגראנג׳ ושל הרוק של שנות התשעים. קורנל המשיך גם בקריירת סולו ובלהקת אודיוסלייב, ומת ב־2017. באותה שנה כמה מהלהקות הגדולות של סיאטל הוציאו אלבומים מצליחים, אבל Superunknown היה אולי השאפתני והמגוון מכולם.''',
'''שמעו את Black Hole Sun ואת Fell on Black Days, ושימו לב לקול של קורנל. ואחר כך שמעו את Paranoid של בלאק סבאת׳ (אלבום 184), כדי לשמוע מאיפה הגיעו הריפים הכבדים.''',
], [
('Black Hole Sun', 'הלהיט, שיר פסיכדלי, מוזר ויפה, עם גיטרה מסתחררת ופזמון ענק.'),
('Fell on Black Days', 'שיר איטי ומרגש על תקופת עצב שמגיעה בלי סיבה ובלי הסבר.'),
('Spoonman', 'שיר קצבי ומשונה, שבו מנגן אמן רחוב מסיאטל בכפיות.'),
])

add(769, [
'''האופספרינג קמו בהנטינגטון ביץ׳ שבדרום קליפורניה בתחילת שנות השמונים, סביב הזמר דקסטר הולנד, שבמקביל ללהקה למד ביולוגיה מולקולרית באוניברסיטה, והגיטריסט נודלס. במשך שנים הם ניגנו פאנק מהיר במועדונים קטנים, בלי הצלחה גדולה. Smash, האלבום השלישי שלהם, יצא ב־1994 בחברת התקליטים העצמאית אפיטף, שהקים ברט גורביץ, הגיטריסט של להקת הפאנק באד רליג׳ן. איש לא ציפה שהוא יהפוך לאחד האלבומים הנמכרים של העשור.''',
'''הצליל הוא פאנק רוק מהיר, ישיר וקליט: גיטרות חזקות ומהירות, תופים דוהרים, פזמונים גדולים שנכתבו לשירה של קהל, ומעט השפעות של מטאל, של סרף ושל מוזיקה מזרח תיכונית. הולנד שר בקול גבוה וחד, על אלימות, על בדידות, על זוגיות מתסכלת ועל החיים בפרברים. Come Out and Play, הלהיט שפתח את הדרך, נבנה על ריף גיטרה עם צליל מזרחי, ועל משפט מדובר שהפך למפורסם, על הצורך להפריד בין כנופיות יריבות. Self Esteem הוא שיר מצחיק ועצוב על בחור שנותן לבחורה לרמוס אותו שוב ושוב, עם פזמון של "לה לה לה". Gotta Get Away מהיר וקצבי, על חרדה ועל הצורך לברוח.''',
'''Smash נמכר ביותר מעשרה מיליון עותקים בעולם, ונחשב לאלבום הנמכר ביותר שיצא אי פעם בחברת תקליטים עצמאית. יחד עם Dookie של גרין דיי (אלבום 784), שיצא באותה שנה, הוא החזיר את הפאנק למצעדים ולרדיו, ופתח את הדרך לגל גדול של להקות פאנק פופ.''',
'''שמעו את Come Out and Play, ואחריו את Basket Case מתוך Dookie (אלבום 784), שני להיטי הפאנק הגדולים של קיץ 1994, ושימו לב כמה הם שונים בסגנון ובאווירה.''',
], [
('Come Out and Play', 'הלהיט, ריף בעל צליל מזרחי ומשפט מדובר מפורסם על כנופיות יריבות.'),
('Self Esteem', 'שיר מצחיק ועצוב על בחור שנותן לבחורה לרמוס אותו, עם "לה לה לה".'),
('Gotta Get Away', 'שיר מהיר וקצבי על חרדה ועל הצורך הדחוף לברוח מהכל.'),
])

add(770, [
'''דרייב לייק ג׳הו היו להקה מסן דייגו, שקמה בסוף שנות השמונים סביב שני גיטריסטים וזמרים, ריק פרוברג וג׳ון רייס. רייס ניגן במקביל גם בלהקת רוקט פרום דה קריפט, שגם היא מופיעה בהמשך (אלבום 791). בתחילת שנות התשעים, כשחברות התקליטים הגדולות חיפשו את נירוונה הבאה, הלהקה הקטנה והמוזרה הזאת זכתה פתאום לחוזה בחברה גדולה. Yank Crime, האלבום השני והאחרון שלהם, יצא ב־1994, והלהקה התפרקה זמן קצר אחר כך. פרוברג ורייס ניגנו יחד עוד קודם, בלהקה בשם פיצ׳פורק, והכירו היטב זה את סגנונו של זה.''',
'''המוזיקה שלהם נקראת פוסט־הארדקור: היא מגיעה מהפאנק המהיר והכועס, אבל השירים ארוכים, מורכבים ומלאים בשינויים פתאומיים. שתי הגיטרות משתלבות זו בזו, לפעמים בצורה מתמטית ומדויקת, ולפעמים בחומה של רעש. הקצבים עוצרים ומשתנים באמצע, ופרוברג צועק בקול צרוד ונואש. יש רגעים שקטים ומהפנטים, ופתאום פיצוץ מטלטל. Here Come the Rome Plows הפותח מתחיל בעוצמה מלאה, ולא נותן לנשום. Luau הוא שיר ארוך, כמעט תשע דקות, שנבנה לאט מקטע שקט ומאיים לשיא סוער. Do You Compute מהיר וזועם, ו־New Math מסובך, משונה ומפתיע.''',
'''האלבום כמעט לא נמכר, אבל עם השנים הפך לאחד האלבומים המשפיעים של הרוק העצמאי האמריקאי, ולהשראה ללהקות רבות של אימו ופוסט־הארדקור. הלהקה התאחדה להופעות רק כעשרים שנה אחר כך. מוזיקאים רבים בלהקות רוק עצמאיות מזכירים אותו עד היום כאחד התקליטים ששינו את הדרך שבה הם מנגנים בגיטרה.''',
'''זה אלבום קשה ורועש. שמעו את Luau עד הסוף, ושימו לב איך הוא נבנה. ואחר כך שמעו את Spiderland של סלינט (אלבום 700), עוד יצירה שמחברת שקט ורעש.''',
], [
('Here Come the Rome Plows', 'הפותח, מתחיל בעוצמה מלאה, עם שתי גיטרות סוערות וצעקות נואשות.'),
('Luau', 'שיר של כמעט תשע דקות, שנבנה לאט משקט מאיים לשיא סוער.'),
('Do You Compute', 'שיר מהיר וזועם, עם קצב שעוצר ומתחיל ושתי גיטרות חדות.'),
])

add(771, [
'''אחרי Modern Life Is Rubbish (אלבום 745), שבו בלר התחילו לכתוב על אנגליה, Parklife, שיצא באפריל 1994, הפך אותם לכוכבים. דיימון אלברן כתב כאן סדרה של שירים על החיים הבריטיים: על פארקים, על חופשות, על מסיבות, על פרברים ועל אנשים רגילים, עם הומור, עם אירוניה ועם הרבה חיבה. האלבום הגיע למקום הראשון במצעד הבריטי, ושנה אחר כך זכתה הלהקה בארבעה פרסי בריט.''',
'''המוזיקה צבעונית ומגוונת מאוד: פופ ריקודים עם סינתיסייזרים, פאנק מהיר, ואלס, שירי מיוזיק הול בריטיים ישנים, בלדות עם כלי מיתר ורוק עם גיטרות. Girls & Boys, הלהיט הראשון, הוא שיר ריקוד קופצני עם בס מקפץ ופזמון מבלבל, על צעירים בחופשה בחוף ים זול. Parklife, שיר הנושא, מושר בחלקו בקול מדבר בידי השחקן פיל דניאלס, במבטא לונדוני כבד, והוא מצחיק וסוחף. End of a Century הוא שיר נוגה ויפה על זוג משועמם, ו־To the End הוא בלדה דרמטית עם כלי מיתר, ושירה בצרפתית של לטישיה סדייה מלהקת סטריאולאב. This Is a Low, הסוגר, הוא שיר גדול ומרגש, שבנוי על התחזית הימית של הרדיו הבריטי.''',
'''Parklife נחשב לאחד האלבומים החשובים של הבריטפופ, ולאחד הסמלים של בריטניה של אמצע שנות התשעים. בשנה שאחריו התפתחה "מלחמת הבריטפופ" המפורסמת בין בלר לאואזיס, כששתי הלהקות הוציאו סינגל באותו יום.''',
'''שמעו את Girls & Boys ואת This Is a Low, ותשמעו את שני הצדדים של בלר: השובב והנוגה. ואחר כך השוו ל־Definitely Maybe של אואזיס (אלבום 767).''',
], [
('Girls and Boys', 'הלהיט, שיר ריקוד קופצני עם בס מקפץ, על צעירים בחופשה בחוף זול.'),
('Parklife', 'שיר הנושא, מושר בחלקו בדיבור במבטא לונדוני כבד, מצחיק וסוחף.'),
('This Is a Low', 'הסוגר, שיר גדול ומרגש, שבנוי על התחזית הימית של הרדיו הבריטי.'),
])

add(772, [
'''ג׳י. לאב, גארט דאטון, גדל בפילדלפיה, והתחיל לנגן בלוז ברחובות ובפאבים של העיר כשהיה עוד נער. הוא אהב את הבלוז הישן של הדלתא של המיסיסיפי, עם גיטרה אקוסטית ומפוחית, אבל גדל גם על היפ הופ, והחליט לחבר את שני העולמות. בבוסטון הוא פגש את המתופף ג׳ף קלמנס ואת הבסיסט ג׳ים פרסקוט, שניגן בקונטרבס, והם הקימו את הלהקה ג׳י. לאב אנד ספיישל סוס. אלבום הבכורה שלהם, שנושא את שם הלהקה, יצא ב־1994.''',
'''המוזיקה פשוטה וחמה: גיטרה אקוסטית או חשמלית ישנה, מפוחית, קונטרבס עמוק ומקפץ, ותופים קלים של היפ הופ וג׳אז. מעל כל זה ג׳י. לאב שר וכמעט מדבר, בקול נינוח, עצלן ומשעשע, שנע בין ראפ לבלוז. השירים עוסקים בדברים פשוטים: בבירה קרה ביום חם, באהבה, בבחורות, בעיר ובמוזיקה עצמה. Cold Beverage, הלהיט, הוא שיר קליל ומצחיק על התשוקה למשקה קר, עם גרוב שאי אפשר לעמוד מולו. Baby's Got Sauce הוא שיר שובב על בחורה עם המון סטייל, ו־Blues Music הוא מחווה רגועה למוזיקה שהוא הכי אוהב. Rhyme for the Summertime קליל ושמשי.''',
'''האלבום כמעט הגיע למעמד של תקליט זהב, בעיקר בזכות הקליפ של Cold Beverage, שהוקרן הרבה ב־MTV. הלהקה המשיכה להוציא אלבומים ולהופיע במשך עשורים, והשפיעה על אמנים שחיברו בין בלוז, פולק והיפ הופ.''',
'''זה אלבום לקיץ, למרפסת ולערב רגוע. שמעו את Cold Beverage, ואחריו את The Healer של ג׳ון לי הוקר (אלבום 637), ותשמעו את השורשים של הבלוז שג׳י. לאב כל כך אוהב.''',
], [
('Cold Beverage', 'הלהיט, שיר קליל ומצחיק על התשוקה למשקה קר, עם גרוב נינוח.'),
('Baby\'s Got Sauce', 'שיר שובב על בחורה עם המון סטייל, עם מפוחית וקונטרבס מקפץ.'),
('Blues Music', 'מחווה רגועה וחמה למוזיקה שהוא הכי אוהב, בגיטרה ובקול נינוח.'),
])

add(773, [
'''עלי פרקה טורה גדל בניאפונקה, כפר על גדת נהר הניז׳ר בצפון מאלי, לא רחוק מטימבוקטו. הוא לימד את עצמו לנגן בגיטרה, אחרי שראה הופעה של להקה גינאית, ופיתח סגנון משלו, שמבוסס על מוזיקה מסורתית של עמים שונים במאלי, ונשמע להפליא כמו הבלוז האמריקאי של ג׳ון לי הוקר. כשהגיע לראשונה לאירופה ולאמריקה, רבים התפלאו לגלות שהבלוז נשמע כאילו חזר הביתה, לאפריקה. Talking Timbuktu, שיצא ב־1994, הוא אלבום משותף שלו עם ריי קודר, גיטריסט אמריקאי ידוע, שאהב מוזיקה מכל העולם.''',
'''האלבום הוקלט בלוס אנג׳לס בתוך כמה ימים בלבד, כמעט בלי חזרות, כאילו מדובר בפגישה של חברים. הגיטרה של טורה חוזרת על מנגינות קצרות ומהפנטות, והקול שלו עמוק, רגוע ושקט, והוא שר בכמה משפות מאלי. קודר מוסיף מעליו גיטרת סלייד מתפתלת ורכה, גיטרה חשמלית ומנדולינה, ובחלק מהשירים מצטרפים נגני ג׳אז ובלוז אמריקאים, ביניהם הגיטריסט והכנר הוותיק קלרנס "גייטמאות׳" בראון. Diaraby, הסוגר, הוא שיר אהבה שקט ויפה, עם גיטרות רכות וקול עמוק, והוא אחד הרגעים היפים באלבום. Ai Du איטי ומהפנט, ו־Bonde, הפותח, קצבי וחם.''',
'''Talking Timbuktu זכה בפרס גראמי לאלבום המוזיקה העולמית, והפך את טורה לכוכב בינלאומי, ולאחד המוזיקאים האפריקאים המפורסמים. כמה שנים אחר כך קודר עשה פרויקט דומה בקובה, עם בואנה ויסטה סושיאל קלאב, שהפך להצלחה ענקית. טורה מת ב־2006.''',
'''זה אלבום לערב רגוע, בשקט. שמעו את Diaraby, ואחריו את The Healer של ג׳ון לי הוקר (אלבום 637), ותשמעו בעצמכם את הקשר המפתיע בין מאלי לבין הדלתא של המיסיסיפי.''',
], [
('Diaraby', 'הסוגר, שיר אהבה שקט ויפה, עם גיטרות רכות וקול עמוק ורגוע.'),
('Ai Du', 'שיר איטי ומהפנט, עם גיטרה חוזרת וגיטרת סלייד מתפתלת של קודר.'),
('Bonde', 'הפותח, שיר קצבי וחם, עם גיטרות משתלבות וקול שקט ובטוח.'),
])

add(774, [
'''הול היא להקה מלוס אנג׳לס, שבראשה עומדת קורטני לאב, זמרת וכותבת עם קול צורמני וכועס ועם נוכחות סוערת, לצד הגיטריסט אריק ארלנדסון. בתחילת שנות התשעים היא נישאה לקורט קוביין מנירוונה, והפכה לאחת הדמויות המצולמות והשנויות במחלוקת של הרוק. Live Through This, האלבום השני של הלהקה, יצא באפריל 1994, ימים ספורים אחרי מותו של קוביין, וכמה חודשים אחר כך מתה גם הבסיסטית הצעירה של הלהקה, קריסטן פאף. שמו של האלבום, "לשרוד את זה", קיבל משמעות כואבת במיוחד.''',
'''המוזיקה מחברת בין פאנק רועש לבין פופ רוק קליט וחזק, עם מנגינות ברורות ופזמונים גדולים. לאב עוברת משירה רכה ומתוקה לצעקה שבורה ומפחידה, והמילים שלה עוסקות בדימוי של נשים, ביופי, באימהות, בתהילה ובכעס על עולם שמנצל אותן. Violet הפותח מתחיל בשקט ומתפוצץ בצעקות. Miss World הוא שיר קליט ומר על מלכת יופי שבורה, ו־Doll Parts הוא שיר שקט ונוגה, בגיטרה אקוסטית, על הרצון להיות נאהבת. Asking for It ו־Softer, Softest עצובים ויפים, ויש גם גרסה ל־Credit in the Straight World של להקת הווייט מרבל ג׳איינטס.''',
'''למרות הצל הכבד של האירועים, Live Through This זכה לשבחים רבים, ונבחר על ידי מבקרים רבים כאחד מאלבומי השנה. הוא נחשב לאחד האלבומים החשובים של רוק נשי בשנות התשעים, והשפיע על זמרות ומוזיקאיות רבות.''',
'''שמעו את Doll Parts ואת Violet, ותשמעו את שני הצדדים של לאב, השקט והצועק. ואחר כך שמעו את Dry של פי. ג׳יי. הארווי (אלבום 732), עוד קול נשי חזק ובלתי מתפשר מאותן שנים.''',
], [
('Doll Parts', 'שיר שקט ונוגה בגיטרה אקוסטית, על הרצון להיות נאהבת, שמתפרץ בסוף.'),
('Violet', 'הפותח, מתחיל בשקט מאיים ומתפוצץ בצעקות ובגיטרות רועשות.'),
('Miss World', 'שיר קליט ומר על מלכת יופי שבורה, עם פזמון גדול.'),
])

add(775, [
'''אחרי Blue Lines (אלבום 703), מסיב אטאק נשארו בלי הזמרת שרה נלסון, שיצאה לקריירת סולו, ונאלצו לחפש קולות חדשים. Protection, שיצא בסוף 1994, הביא כמה כאלה: טרייסי ת׳ורן, הזמרת של הצמד אברית׳ינג בט דה גירל, הזמרת ניקולט, בעלת קול גבוה ומיוחד מעולם המוזיקה האלקטרונית, והוראס אנדי הוותיק, לצד טריקי, שעוד ראפ כאן לפני שיצא לדרך משלו. את עיבודי כלי המיתר כתב קרייג ארמסטרונג, מלחין סקוטי שעבד אחר כך על פסקולים רבים לסרטים.''',
'''הצליל רך, איטי וחלומי עוד יותר מבאלבום הראשון: קצבי היפ הופ עצלים, בס עמוק, כלי מיתר, פסנתר וקולות שקטים, שיוצרים אווירה של לילה עירוני חם. Protection, שיר הנושא, הוא שיר אהבה ארוך ומרגש, שבו טרייסי ת׳ורן שרה בקול חם ושקט על הרצון להגן על מישהו אהוב, מעל קצב איטי ומהפנט. Karmacoma הוא שיר מוזר ומאיים, עם ראפ לוחש של טריקי ושל 3D. Sly, בשירתה של ניקולט, מתחיל בכלי מיתר מזרחיים ונבנה לשיר דרמטי ויפה. Spying Glass הוא רגאיי איטי עם הוראס אנדי, ו־Weather Storm הוא קטע כלי שקט ויפה, עם פסנתר. יש גם גרסה חיה לשיר Light My Fire של הדורז.''',
'''Protection נמכר היטב, והוכיח שמסיב אטאק הם יותר מלהקה של אלבום אחד. שנה אחר כך יצאה גרסת דאב שלמה של האלבום, No Protection, בעיבוד של המפיק מד פרופסור, שהפכה גם היא לאהובה. הלהקה המשיכה עם אלבום אפל עוד יותר, Mezzanine, שהפך לאחד המצליחים שלה.''',
'''שמעו את Protection באוזניות, בשעת לילה, ותנו לו לזרום. ואחר כך שמעו את Maxinquaye של טריקי (אלבום 788), ותשמעו לאן לקח טריקי את Karmacoma.''',
], [
('Protection', 'שיר הנושא, שיר אהבה ארוך ומרגש, עם קולה החם והשקט של טרייסי ת׳ורן.'),
('Karmacoma', 'שיר מוזר ומאיים, עם ראפ לוחש של טריקי ושל 3D וקצב איטי.'),
('Sly', 'מתחיל בכלי מיתר מזרחיים ונבנה לשיר דרמטי ויפה בקולה של ניקולט.'),
])

add(776, [
'''המאניק סטריט פריצ׳רס הם להקה מעיירה קטנה בדרום ויילס, שהתחילה בתחילת שנות התשעים עם דימוי פרובוקטיבי, הצהרות גדולות ושירים פוליטיים. הזמר והגיטריסט ג׳יימס דין בראדפילד והמתופף שון מור כתבו את המוזיקה, והבסיסט ניקי וייר והגיטריסט ריצ׳י אדוארדס כתבו את רוב המילים. The Holy Bible, האלבום השלישי שלהם, יצא ב־1994, בתקופה קשה מאוד ללהקה, ובעיקר לאדוארדס, שהיה אז במצב נפשי ירוד.''',
'''זה אלבום אפל, כועס וקשה, אבל גם חכם ומרתק. המילים, שרובן נכתבו בידי אדוארדס, צפופות מאוד, מלאות במילים מסובכות ובציטוטים, ועוסקות בנושאים קשים: בפוליטיקה, בהיסטוריה של המאה העשרים ובזוועותיה, בגוף, בחולי ובשנאה עצמית. המוזיקה חדה ויבשה, עם גיטרות מהירות ועוקצניות בהשפעת הפוסט־פאנק, ובראדפילד שר בעוצמה ובמהירות, כמעט בלי לנשום. Faster הוא שיר מהיר וכועס, עם מילים חדות ופזמון מתפוצץ. This Is Yesterday הוא שיר שקט, מלודי ועצוב, על געגוע לעבר. Yes, הפותח, קליט ומר. P.C.P. מהיר וזועם, ו־Die in the Summertime כבד ומאיים.''',
'''כמה חודשים אחרי צאת האלבום, בתחילת 1995, ריצ׳י אדוארדס נעלם, ומעולם לא נמצא. הלהקה המשיכה כשלישייה, והפכה לאחת הלהקות הגדולות בבריטניה, עם שירים פופולריים ומלודיים יותר. The Holy Bible לא נמכר היטב בזמנו, אבל נחשב היום לאחד האלבומים החשובים והאמיצים של הרוק הבריטי של התקופה.''',
'''זה אלבום קשה להאזנה, בגלל הנושאים שלו. התחילו מ־This Is Yesterday, הרך ביותר, ורק אחר כך עברו ל־Faster. ואחר כך שמעו את Entertainment! של גאנג אוף פור (אלבום 444), אחת ההשראות של הלהקה.''',
], [
('Faster', 'שיר מהיר וכועס, עם מילים חדות, גיטרות עוקצניות ופזמון מתפוצץ.'),
('This Is Yesterday', 'שיר שקט, מלודי ועצוב, על געגוע לעבר ולימים פשוטים יותר.'),
('Yes', 'הפותח, שיר קליט ומר, עם גיטרות מהירות ושירה עוצמתית.'),
])

add(777, [
'''אחרי ההצלחה של אלבום הבכורה (אלבום 733), סוויד היו אחת הלהקות החמות בבריטניה, אבל במהלך העבודה על האלבום השני היחסים בין הזמר ברט אנדרסון לגיטריסט ברנרד באטלר התדרדרו לגמרי. אנדרסון הסתגר בבית בלונדון וכתב שירים אפלים ושאפתניים, באטלר רצה עיבודים גדולים ותזמורתיים, והמתח ביניהם הלך וגבר. באטלר עזב את הלהקה עוד לפני שהאלבום הושלם. Dog Man Star, שיצא בסוף 1994, הוא התוצאה: אלבום גדול, דרמטי ושונה מאוד מהבריטפופ השמח של אותה תקופה.''',
'''הצליל עשיר, תיאטרלי ומלא רגש: גיטרות מתפתלות ומבריקות של באטלר, פסנתר, תזמורת כלי מיתר, ואנדרסון ששר בקול גבוה ומתנגן על אהבה, על תהילה, על בדידות ועל חלומות שנשברים. האלבום נשמע לעתים כמו מחזמר אפל או כמו סרט ישן מהוליווד. The Wild Ones הוא שיר אהבה רחב ויפה, אחד השירים הגדולים שלהם, עם מנגינה שעולה ועולה. New Generation הוא שיר קצבי ושמח יותר, עם גיטרות חזקות. We Are the Pigs דרמטי ומאיים, עם כלי נשיפה. Still Life, הסוגר, הוא בלדה עם תזמורת שלמה, על אישה שמחכה ליד החלון. The Asphalt World ארוך, אפל ומהפנט.''',
'''Dog Man Star לא נמכר כמו קודמו, ובזמנו נחשב לכישלון יחסי, אבל עם השנים הפך לאחד האלבומים המוערכים של התקופה, ורבים רואים בו את יצירת המופת של סוויד. הלהקה המשיכה עם גיטריסט צעיר חדש, ונהנתה מהצלחה גדולה עם אלבום פופי וקליל יותר.''',
'''שמעו את The Wild Ones ואת Still Life, ושימו לב לכלי המיתר ולקול של אנדרסון. ואחר כך חזרו לאלבום הבכורה שלהם (אלבום 733), והשוו בין השניים.''',
], [
('The Wild Ones', 'שיר אהבה רחב ויפה, עם מנגינה שעולה ועולה, אחד השירים הגדולים שלהם.'),
('Still Life', 'הסוגר, בלדה עם תזמורת שלמה על אישה שמחכה ליד החלון.'),
('New Generation', 'שיר קצבי ושמח, עם גיטרות חזקות ומבריקות ופזמון גדול.'),
])

add(778, [
'''כריסטופר וואלאס, שנודע בשמות ביגי סמולס והנוטוריוס בי.איי.ג׳י., גדל בבדפורד־סטייבסנט שבברוקלין, בנה של אם יחידנית שעבדה כמורה. הוא התחיל לראפ ברחוב, וקלטת שהקליט הגיעה לשון "פאפי" קומבס, מפיק צעיר ושאפתן, שהקים באותם ימים חברת תקליטים חדשה בשם בד בוי. Ready to Die, אלבום הבכורה שלו, יצא ב־1994, והפך אותו כמעט מיד לאחד הראפרים החשובים בניו יורק, ולמנהיג של ההיפ הופ של החוף המזרחי.''',
'''האלבום בנוי כמו סיפור חיים, מלידה ועד מוות, עם קטעי מעבר קטנים בין השירים. בצד אחד יש שירים קשים ואפלים על פשע, על עוני ועל ייאוש, ובצד שני להיטים חמים ומלאי הומור, עם דגימות של סול ופאנק משנות השבעים והשמונים. הקול של ביגי עמוק, עגול ונינוח, והזרימה שלו קלה ומדויקת, עם חוש הומור חד וסיפור מרתק. Juicy, הלהיט הראשון, הוא שיר על הדרך מעוני להצלחה, שמוקדש למי שלא האמינו בו, ונבנה על דגימה מתוך שיר של להקת מטום. Big Poppa הוא שיר מסיבה חלק ונינוח, עם דגימה של האחים איזלי. Things Done Changed הוא תיאור עצוב של שכונה שהשתנתה לרעה. המילים בוטות מאוד בחלק מהשירים.''',
'''Ready to Die נחשב לאחד מאלבומי ההיפ הופ הגדולים בכל הזמנים. ביגי נרצח ב־1997, בגיל עשרים וארבע בלבד, כשבועיים לפני שיצא אלבומו השני, וזכרו נשאר חי מאוד בתרבות ההיפ הופ עד היום.''',
'''שמעו את Juicy, ושימו לב לסיפור שלו מההתחלה ועד הסוף. ואחר כך שמעו את Illmatic של נאס (אלבום 762), עוד אלבום בכורה ניו יורקי גדול מאותה שנה.''',
], [
('Juicy', 'הלהיט, סיפור הדרך מעוני להצלחה, עם דגימה חמה של שיר סול ישן.'),
('Big Poppa', 'שיר מסיבה חלק ונינוח, עם קול עמוק ודגימה של האחים איזלי.'),
('Things Done Changed', 'תיאור עצוב וכן של שכונה שהשתנתה לרעה במשך השנים.'),
])

add(779, [
'''ג׳ף באקלי היה בנו של טים באקלי, זמר הפולק המופלא שכבר פגשנו באתר (אלבומים 86, 160 ו־260), אבל כמעט לא הכיר את אביו, שעזב את הבית כשג׳ף היה תינוק ומת צעיר. בתחילת שנות התשעים הופיע ג׳ף לבדו עם גיטרה חשמלית בבית קפה קטן במזרח מנהטן, ושר שם שירים משלו ושל אחרים, משירי קוואלי של נוסרת פתח עלי ח׳אן (אלבום 731) ועד שירים של אדית פיאף. הקול שלו, הטווח העצום שלו והנוכחות שלו משכו מבקרים וחברות תקליטים, ו־Grace, אלבום הבכורה שלו, יצא ב־1994.''',
'''הקול של באקלי הוא הלב של האלבום: הוא יכול לשיר בשקט ובעדינות, כמעט בלחישה, ואז לטפס לגבהים מדהימים, לצעוק ולבכות. הלהקה מנגנת רוק חזק ורחב, עם גיטרות מהדהדות, ולצידו יש רגעים שקטים ואינטימיים. Hallelujah, השיר של לאונרד כהן, הוא כאן גרסה שקטה ושבורה בגיטרה חשמלית ובקול בלבד, שהפכה עם השנים לאחת המפורסמות של השיר, ולגרסה שבזכותה העולם הכיר אותו. Grace, שיר הנושא, הוא שיר דרמטי וסוחף על אהבה ועל מוות. Lover, You Should've Come Over הוא שיר פרידה ארוך ומרגש, עם עוגב. Last Goodbye קצבי ויפה, ו־Corpus Christi Carol הוא שיר מימי הביניים, שהוא שר בקול גבוה ושקוף.''',
'''Grace לא נמכר הרבה בזמנו, אבל מוזיקאים רבים העריצו אותו, ועם השנים הוא הפך לאחד האלבומים האהובים של העשור. באקלי טבע בנהר בממפיס ב־1997, בזמן שעבד על אלבומו השני, והוא היה רק בן שלושים.''',
'''שמעו את Hallelujah בשקט, ואחריו את Songs of Leonard Cohen (אלבום 114), כדי להכיר את הכותב. ואחר כך שמעו את Happy Sad של טים באקלי (אלבום 160), ותשמעו את הקול של האב.''',
], [
('Hallelujah', 'גרסה שקטה ושבורה לשיר של לאונרד כהן, רק גיטרה חשמלית וקול.'),
('Grace', 'שיר הנושא, דרמטי וסוחף, על אהבה ועל מוות, עם קול שמטפס לשמיים.'),
('Lover, You Should\'ve Come Over', 'שיר פרידה ארוך ומרגש, עם עוגב וקול מלא געגוע.'),
])

add(780, [
'''אחרי "האלבום החום" (אלבום 750), האחים פול ופיל הרטנול מאורביטל הפכו לאחת להקות הריקודים החשובות בבריטניה, עם הופעה בלתי נשכחת בפסטיבל גלסטונברי. Snivilisation, שיצא ב־1994, הוא האלבום השלישי שלהם, והוא פוליטי ומהורהר יותר. השם הוא משחק מילים על המילה "ציוויליזציה", והאלבום עוסק בחברה המודרנית, בצרכנות, בטכנולוגיה, בזיהום ובחוק חדש של אותה שנה שהגביל את מסיבות הרייב בבריטניה.''',
'''המוזיקה עדיין אלקטרונית, עם קצבים, סינתיסייזרים ומנגינות שנבנים לאט, אבל היא מגוונת וניסיונית יותר מבעבר: יש קטעים שקטים ואווירתיים, קטעים קצביים ומהירים, דגימות של קולות ושל חדשות, ואפילו רגעים של ג׳אז ודראם אנד בייס. בשני קטעים שרה הזמרת הצעירה אליסון גולדפראפ, שהפכה מאוחר יותר לכוכבת בעצמה. Are We Here? הוא קטע ארוך ומרחף, עם קולה של גולדפראפ וקצב מהיר ושבור. Forever הוא קטע רגוע ויפה, עם מנגינה מתמשכת. Attached, הסוגר, ארוך ומרגש, נבנה לאט לשיא גדול. Sad But True ו־I Wish I Had Duck Feet משונים ומצחיקים, ו־Crash and Carry לועג לצרכנות. האחים מנגנים את הקטעים האלה גם בהופעות, כשהם עומדים מאחורי שולחנות מלאים בציוד, עם פנסים קטנים על המצח.''',
'''Snivilisation נחשב לאחד האלבומים הטובים של אורביטל, והוכיח שמוזיקה אלקטרונית יכולה להיות גם מוזיקה עם מסר. הוא הגיע לעשירייה הראשונה במצעד הבריטי, ואורביטל המשיכו להופיע עם המוזיקה הזאת בפסטיבלים גדולים בכל העולם.''',
'''שמעו את Attached עד הסוף, ותנו לו להתפתח. ואחר כך שמעו את Music for the Jilted Generation של הפרודיג׳י (אלבום 783), עוד אלבום מאותה שנה שמגיב לאותו חוק נגד מסיבות.''',
], [
('Are We Here?', 'קטע ארוך ומרחף, עם קולה של אליסון גולדפראפ וקצב מהיר ושבור.'),
('Forever', 'קטע רגוע ויפה, עם מנגינה מתמשכת וקצב רך ומהפנט.'),
('Attached', 'הסוגר, קטע ארוך ומרגש שנבנה לאט לשיא גדול ומשחרר.'),
])

add(781, [
'''בנובמבר 1993 הקליטה נירוונה הופעה מיוחדת לסדרה של ערוץ MTV, שבה להקות רוק מנגנות בכלים אקוסטיים. הבמה עוצבה כמו הלוויה, עם חבצלות לבנות ונרות, וקורט קוביין התעקש לנגן מעט להיטים ויותר שירים של אחרים, כולל של להקות קטנות ולא מוכרות שאהב. לצד חברי הלהקה ניגנו הגיטריסט פט סמיר והצ׳לנית לורי גולדסטון. ההופעה שודרה בטלוויזיה, וכמה חודשים אחר כך, באפריל 1994, קוביין מת. MTV Unplugged in New York יצא באלבום בנובמבר 1994, והפך לפרידה שלו.''',
'''הצליל שקט, חשוף ועצוב: גיטרות אקוסטיות, צ׳לו, תופים עדינים, וקולו של קוביין, שבור, עייף ומלא רגש, כאילו הוא שר רק לחברים בחדר. השירים של נירוונה, כמו About a Girl, Come as You Are ו־All Apologies, נשמעים כאן רכים ופגיעים מתמיד. The Man Who Sold the World הוא גרסה מהפנטת לשיר של דייוויד בואי. שלושה שירים של להקת המיט פאפטס (אלבום 529) מבוצעים יחד עם שני האחים קירקווד מהלהקה עצמה. ובסוף, Where Did You Sleep Last Night, שיר עממי אמריקאי ישן בגרסה של לד בלי, שבו קוביין מסיים בצעקה כואבת ומצמררת, אחד הרגעים המפורסמים בתולדות הרוק.''',
'''האלבום הגיע למקום הראשון במצעד האמריקאי, זכה בפרס גראמי, ונחשב לאחד מאלבומי ההופעה החיה החשובים שהוקלטו אי פעם. הוא הראה צד שקט, עדין ומוזיקלי מאוד של נירוונה, שרבים לא הכירו.''',
'''שמעו את האלבום ברצף, בשקט, ושימו לב לשתיקה של הקהל. ואחר כך שמעו את Meat Puppets II (אלבום 529), כדי להכיר את המקור לשלושת השירים המוזרים והיפים.''',
], [
('Where Did You Sleep Last Night', 'שיר עממי ישן, שקוביין מסיים בצעקה כואבת ומצמררת.'),
('The Man Who Sold the World', 'גרסה מהפנטת ושקטה לשיר של דייוויד בואי, עם צ׳לו וגיטרה.'),
('About a Girl', 'הפותח, שיר אהבה מוקדם של נירוונה, שנשמע כאן רך ופגיע במיוחד.'),
])

add(782, [
'''ניין אינץ׳ ניילס הם בעצם טרנט רזנור, מוזיקאי מקליבלנד שכתב, ניגן והפיק כמעט הכל בעצמו, ושילב בין רוק כבד לבין מוזיקה אלקטרונית ותעשייתית. אלבום הבכורה שלו הצליח, ול־The Downward Spiral, שיצא ב־1994, הוא שכר בית בלוס אנג׳לס והפך אותו לאולפן. יחד עם המפיק פלאד, שעבד גם עם דפש מוד ועם U2, הוא בנה אלבום קונספט על אדם שמתפרק לאט לאט, נפשית, ומאבד את כל מה שיש לו. רזנור עבד על האלבום זמן רב, והקפיד על כל צליל קטן, כמו צייר שעובד על ציור אחד גדול.''',
'''הצליל עשיר, אפל ומטלטל: תופים אלקטרוניים, גיטרות מעוותות, סינתיסייזרים, דגימות של רעשים, ורגעים שקטים עם פסנתר. השירים עוברים מלחישה לצעקה, משקט לרעש, ובונים עולם קודר ומפחיד. Closer הוא שיר איטי ומהפנט, עם קצב כבד וסינתיסייזר מפורסם, והמילים שלו בוטות. March of the Pigs מהיר ומטורף, ופתאום עוצר לפסנתר עליז. Piggy שקט ומאיים. A Warm Place הוא קטע כלי שקט ויפה, כמו רגע של מנוחה. Hurt, הסוגר, הוא שיר עצוב ושביר, שמתחיל בלחישה ונבנה לרעש גדול. כמה שנים אחר כך הקליט אותו ג׳וני קאש, בגרסה שהפכה לאחד הרגעים המרגשים של סוף חייו.''',
'''The Downward Spiral נמכר במיליוני עותקים, ונחשב לאחד האלבומים החשובים של שנות התשעים. הוא הוכיח שמוזיקה תעשייתית קשה יכולה להגיע לקהל ענק. רזנור המשיך גם לכתוב פסקולים לסרטים, וזכה בפרס אוסקר.''',
'''זה אלבום קשה ואפל, שעוסק בנושאים כואבים. התחילו מ־Hurt, ואחריו שמעו את Psalm 69 של מיניסטרי (אלבום 725), עוד אלבום של רוק תעשייתי מאותה תקופה.''',
], [
('Hurt', 'הסוגר, שיר עצוב ושביר שמתחיל בלחישה, וג׳וני קאש הקליט לו גרסה מפורסמת.'),
('March of the Pigs', 'שיר מהיר ומטורף, שעוצר פתאום לפסנתר עליז ומפתיע.'),
('A Warm Place', 'קטע כלי שקט ויפה, כמו רגע של מנוחה באמצע הסערה.'),
])

add(783, [
'''הפרודיג׳י נולדו בבריינטרי, עיירה באסקס, סביב ליאם האולט, תקליטן ומפיק צעיר שבנה את המוזיקה בחדר השינה שלו, ולצידו רקדנים ואנשי במה פרועים: קית׳ פלינט, ליירוי תורנהיל ו־MC מקסים. הם התחילו בסצנת מסיבות הרייב של תחילת שנות התשעים, עם להיטים מהירים ושמחים. Music for the Jilted Generation, האלבום השני שלהם, יצא ב־1994, בזמן שבבריטניה עבר חוק חדש שהגביל מאוד את מסיבות הרייב, והאלבום הוא במידה רבה תגובה כועסת אליו. הוא הגיע למקום הראשון במצעד הבריטי.''',
'''הצליל קשה, כבד ואפל יותר מבעבר: קצבי ברייקביט מהירים ושבורים, בס עמוק, סינתיסייזרים צורמים, דגימות של קולות ושל סרטים, ובחלק מהשירים גם גיטרות חשמליות כבדות, שמחברות בין מוזיקת מסיבות לרוק. Voodoo People נבנה על ריף גיטרה מהפנט וקצב מהיר, והוא אחד הקטעים המפורסמים שלהם. No Good (Start the Dance) הוא שיר ריקוד שמח וסוחף, עם קול נשי שחוזר על עצמו. Poison איטי, כבד ומאיים, עם קצב שנשמע כמו פטיש. Their Law, עם להקת הפופ וויל איט איטסלף, הוא שיר מחאה רועש וגיטרי נגד החוק החדש. The Narcotic Suite, בשלושה חלקים, סוגר את האלבום בשקט יחסי, עם חליל.''',
'''האלבום נחשב לאחד האלבומים החשובים של המוזיקה האלקטרונית הבריטית, והוכיח שהיא יכולה להיות כועסת ופוליטית כמו פאנק. אחריו הפכו הפרודיג׳י לאחת הלהקות הגדולות בעולם, עם האלבום The Fat of the Land.''',
'''שמעו את Voodoo People בווליום גבוה, ואחריו את Snivilisation של אורביטל (אלבום 780), עוד אלבום מאותה שנה שעוסק באותו חוק, בדרך שקטה ומהורהרת יותר.''',
], [
('Voodoo People', 'ריף גיטרה מהפנט וקצב מהיר, אחד הקטעים המפורסמים של הלהקה.'),
('No Good (Start the Dance)', 'שיר ריקוד שמח וסוחף, עם קול נשי שחוזר שוב ושוב.'),
('Poison', 'שיר איטי, כבד ומאיים, עם קצב שנשמע כמו פטיש.'),
])

add(784, [
'''גרין דיי קמו בברקלי ובאזור המפרץ של סן פרנסיסקו, מתוך סצנת פאנק קטנה שהתרכזה סביב מועדון שבו הלהקות ניגנו לקהל של בני נוער. במרכזה עמדו שלושה חברים: הזמר והגיטריסט בילי ג׳ו ארמסטרונג, הבסיסט מייק דירנט והמתופף טרה קול. אחרי שני אלבומים בחברה עצמאית, הם חתמו בחברת תקליטים גדולה, צעד שרבים בסצנה ראו כבגידה. Dookie, שיצא ב־1994, הפך אותם בבת אחת לאחת הלהקות הגדולות בעולם.''',
'''המוזיקה היא פאנק פופ מהיר, קצר וקליט: שלושה כלים, גיטרות חזקות, תופים מהירים, ופזמונים מתוקים שקל לשיר. ארמסטרונג שר בקול צעיר, מתלונן ומצחיק, על שעמום, על עצלות, על חרדה, על אהבה ועל חוסר כיוון בחיים. Basket Case הוא שיר מהיר ומצחיק על התקפי חרדה, שהפך לאחד מלהיטי הרוק הגדולים של העשור. Longview הוא שיר על שעמום מוחלט, עם קו בס מפורסם. When I Come Around הוא שיר רגוע יותר, עם ריף פשוט וקליט, ו־Welcome to Paradise מספר על החיים בבית נטוש ומוזנח עם חברים. She ו־Burnout קצרים וחזקים. האלבום הופק על ידי רוב קבאלו, שנתן לפאנק הגולמי שלהם צליל נקי וחזק, בלי לאבד את האנרגיה.''',
'''Dookie נמכר ביותר מעשרה מיליון עותקים בארצות הברית, זכה בפרס גראמי, והחזיר את הפאנק לרדיו ולמצעדים. הופעה של הלהקה בפסטיבל וודסטוק 94, שהסתיימה בקרב בוץ עם הקהל, הפכה למפורסמת. גרין דיי המשיכו להצלחה גדולה במשך עשרות שנים.''',
'''שמעו את Basket Case ואת Longview, ושימו לב לבס. ואחר כך שמעו את Ramones (אלבום 363), כדי לשמוע את סבא רבא של הפאנק הקצר והמהיר.''',
], [
('Basket Case', 'שיר מהיר ומצחיק על התקפי חרדה, אחד מלהיטי הרוק הגדולים של העשור.'),
('Longview', 'שיר על שעמום מוחלט, עם קו בס מפורסם ופזמון צועק.'),
('When I Come Around', 'שיר רגוע יותר, עם ריף פשוט וקליט ומנגינה חמה.'),
])

add(785, [
'''דייב גרוהל היה המתופף של נירוונה, ובמשך שנים כתב בסתר שירים משלו והקליט אותם בבית, בלי לספר כמעט לאיש. אחרי מותו של קורט קוביין באפריל 1994, הוא לא ידע אם ירצה בכלל להמשיך לנגן. בסתיו של אותה שנה נכנס לאולפן בסיאטל לשבוע, והקליט כמעט לבד אלבום שלם, כשהוא מנגן בעצמו בכל הכלים ושר. השם, פו פייטרס, לקוח מכינוי שנתנו טייסים במלחמת העולם השנייה לעצמים מעופפים לא מזוהים. כשההקלטות התחילו להתפשט, הוא הקים סביבן להקה אמיתית, והאלבום יצא ב־1995.''',
'''המוזיקה היא רוק אלטרנטיבי אנרגטי ושמח יותר מזה של נירוונה, עם גיטרות חזקות, תופים עוצמתיים, כמובן, ומנגינות פופ קליטות. גרוהל שר בקול שעובר בקלות מרכות לצעקה. This Is a Call, הסינגל הראשון, הוא שיר רוק קצבי וסוחף, עם פזמון גדול. I'll Stick Around הוא שיר כועס וחזק, ו־Big Me הוא שיר פופ קצר, רך ומתוק, שהקליפ שלו, פרודיה על פרסומת לסוכריות, הפך למפורסם. Alone + Easy Target ו־Good Grief מהירים ורועשים. בשיר X-Static מנגן גיטרה גם גרג דולי מהאפגן וויגס (אלבום 738), חבר של גרוהל.''',
'''האלבום הצליח מאוד, והוכיח שגרוהל הוא גם כותב וזמר מוכשר, לא רק מתופף. פו פייטרס הפכו לאחת הלהקות הגדולות והאהובות בעולם, עם להיטים רבים ועשרות שנים של הופעות באצטדיונים. גרוהל עבר בלהקה החדשה מהתופים לגיטרה ולשירה, והפך לאחד הפרצופים המוכרים והחביבים של הרוק.''',
'''שמעו את This Is a Call ואת Big Me, ואחריהם את In Utero של נירוונה (אלבום 741), ותשמעו כמה שונה גרוהל כשהוא מוביל, בתופים ובגיטרה.''',
], [
('This Is a Call', 'הסינגל הראשון, שיר רוק קצבי וסוחף, עם פזמון גדול ומשחרר.'),
('Big Me', 'שיר פופ קצר, רך ומתוק, עם קליפ מצחיק שהפך למפורסם.'),
('I\'ll Stick Around', 'שיר כועס וחזק, עם גיטרות עבות וצעקות בפזמון.'),
])

add(786, [
'''בוץ׳ ויג היה אחד המפיקים החשובים של תחילת שנות התשעים: הוא הפיק את Nevermind של נירוונה (אלבום 685), את Siamese Dream של הסמאשינג פאמפקינס (אלבום 735) ואת Dirty של סוניק יות׳ (אלבום 723). יחד עם שני חבריו מהאולפן שלו בוויסקונסין, דיוק אריקסון וסטיב מרקר, הוא החליט להקים להקה משלו, שתחבר בין רוק לבין מוזיקה אלקטרונית ודגימות. הם ראו בטלוויזיה קליפ של זמרת סקוטית צעירה, שירלי מנסון, והזמינו אותה להצטרף. Garbage, אלבום הבכורה שלהם, יצא ב־1995.''',
'''הצליל מבריק, חזק ומלוטש: גיטרות מעוותות, קצבים אלקטרוניים, דגימות, סינתיסייזרים וקלידים, שנבנים לשכבות עבות ומדויקות באולפן. ובמרכז עומדת מנסון, עם קול נמוך, קר ומפתה, ועם נוכחות חזקה וביטחון עצמי, שמשלבת בין כעס, הומור ופגיעות. Only Happy When It Rains הוא שיר מצחיק ומרגש על מישהי שאוהבת להיות עצובה, עם פזמון ענק. Stupid Girl, הלהיט הגדול, נבנה על קצב תופים לקוח מתוך Train in Vain של הקלאש, והוא שיר חד ועוקצני. Queer הוא שיר איטי, אפל ומאיים, ו־Vow, הסינגל הראשון, רועש וזועם. Milk, הסוגר, איטי ועצוב. ויג וחבריו הקליטו את האלבום באולפן שלהם במדיסון, וויסקונסין, ובילו חודשים בשכבות, בדגימות ובפרטים.''',
'''האלבום נמכר במיליוני עותקים, והפך את גרבג׳ לאחת הלהקות המצליחות של סוף שנות התשעים, ואת מנסון לאחת הנשים הבולטות ברוק. הם אף הקליטו את שיר הנושא לסרט של ג׳יימס בונד.''',
'''שמעו את Stupid Girl, ואחריו את Train in Vain מתוך London Calling של הקלאש (אלבום 438), ותשמעו את מקור התופים.''',
], [
('Only Happy When It Rains', 'שיר מצחיק ומרגש על מישהי שאוהבת להיות עצובה, עם פזמון ענק.'),
('Stupid Girl', 'הלהיט, שיר חד ועוקצני, על קצב תופים לקוח מהקלאש.'),
('Queer', 'שיר איטי, אפל ומאיים, עם קול נמוך, לוחש ומפתה.'),
])

add(787, [
'''ניגטמרס און וואקס הוא בעיקר ג׳ורג׳ אוולין, תקליטן ומפיק מלידס שבצפון אנגליה, שגדל על סול, רגאיי, פאנק והיפ הופ, והתחיל את דרכו בבריקדאנס ובמסיבות. הוא היה מהאמנים הראשונים של וורפ, חברת התקליטים משפילד שנודעה במוזיקה אלקטרונית ניסיונית. Smokers Delight, האלבום השני שלו, יצא ב־1995, והוא אחד האלבומים החשובים של הדאון־טמפו, מוזיקה אלקטרונית איטית ונינוחה, שנועדה להאזנה בבית ולא לריקודים.''',
'''המוזיקה איטית, חמה ומרגיעה: קצבי היפ הופ עצלים, בס עמוק של רגאיי ודאב, דגימות של סול ושל ג׳אז משנות השבעים, כלי מיתר, קולות נשיים רכים, וצלילים קטנים שמרחפים ונעלמים. אין כאן כמעט מילים, והקטעים זורמים זה לתוך זה כמו מסע אחד ארוך. Nights Introlude הפותח נבנה על דגימה של ריף מפורסם של קווינסי ג׳ונס, ונשמע כמו כניסה איטית ללילה חם. Dreddoverboard הוא דאב איטי ועמוק, עם בס ענק. Pipes Honour הוא קטע ארוך, כמעט עשר דקות, שנבנה לאט ומהפנט. Groove Street ו־Cruise (Don't Stop) קופצניים ושמחים יותר, ו־Gambia via Vagator Beach רגוע וחלומי, כמו חוף ים בערב. הכל נשמע חם, רך ומעט מעושן, כמו חדר עם תאורה עמומה בשעה מאוחרת.''',
'''Smokers Delight נחשב לאחד האלבומים החשובים של המוזיקה האלקטרונית הבריטית האיטית, לצד אלבומי הטריפ הופ של בריסטול. אוולין המשיך להוציא אלבומים במשך עשרות שנים, ומוזיקה שלו מופיעה בסרטים, בסדרות ובפרסומות.''',
'''זה אלבום לערב רגוע, למרפסת או לספה. שמעו את Nights Introlude, ואחריו את Passin' Me By של הפארסייד (אלבום 719), שנבנה על אותה דגימה של קווינסי ג׳ונס.''',
], [
('Nights Introlude', 'הפותח, דגימה של קווינסי ג׳ונס וקצב איטי, כמו כניסה ללילה חם.'),
('Dreddoverboard', 'דאב איטי ועמוק, עם בס ענק וצלילים שמרחפים ונעלמים.'),
('Pipes Honour', 'קטע ארוך שנבנה לאט ומהפנט, כמעט עשר דקות של שקט חם.'),
])

add(788, [
'''טריקי, אדריאן ת׳וז, גדל בבריסטול, ואמו, מקסין קוויי, מתה כשהיה בן ארבע בלבד. הוא היה חלק מהחבורה של מסיב אטאק, וראפ בקול לוחש ומחוספס ב־Blue Lines (אלבום 703) וב־Protection (אלבום 775), עד שהחליט לצאת לדרך משלו. Maxinquaye, אלבום הבכורה שלו, יצא ב־1995, ושמו הוא מחווה לאמו. את רוב השירים שרה מרטינה טופלי־בירד, נערה צעירה מבריסטול שטריקי פגש במקרה, שקולה הרך והקר הפך לסימן ההיכר של האלבום.''',
'''המוזיקה אפלה, מוזרה, חושנית ומאיימת: קצבים איטיים ועכורים, בס עמוק, דגימות מעוותות של רוק, היפ הופ, ג׳אז ופסקולים, רעשים וצלילים לא צפויים. טריקי לוחש ונוהם, ומרטינה שרה מעליו בשקט, כמו שני קולות של אותו חלום רע. Overcome, הפותח, הוא גרסה חדשה ואיטית ל־Karmacoma, השיר של מסיב אטאק. Hell Is Round the Corner נבנה על אותה דגימה של אייזק הייז שמופיעה גם ב־Glory Box של פורטיסהד (אלבום 760). Black Steel היא גרסה מפתיעה, רוקיסטית ורועשת, לשיר של פבליק אנמי (אלבום 634), שמרטינה שרה. Ponderosa ו־Aftermath איטיים ומהפנטים.''',
'''Maxinquaye זכה לשבחים עצומים, ומבקרים רבים בחרו בו לאלבום השנה של 1995. הוא נחשב לאחד האלבומים החשובים והמקוריים של התקופה, והשפיע על מוזיקה אלקטרונית, על היפ הופ ועל רוק אלטרנטיבי. טריקי המשיך להוציא אלבומים ניסיוניים ומוזרים. האלבום נשמע עד היום מוזר וחדשני, כאילו הוקלט מחר ולא לפני שלושים שנה.''',
'''שמעו את Hell Is Round the Corner ואחריו את Glory Box (אלבום 760), ותשמעו איך שני אמנים מבריסטול השתמשו באותה דגימה בשתי דרכים שונות לגמרי.''',
], [
('Hell Is Round the Corner', 'קצב איטי ועכור ודגימה של אייזק הייז, עם לחישות ושירה רכה.'),
('Black Steel', 'גרסה רועשת ומפתיעה לשיר של פבליק אנמי, בקולה של מרטינה.'),
('Overcome', 'הפותח, גרסה חדשה ואיטית ל־Karmacoma של מסיב אטאק.'),
])

add(789, [
'''ראקוון, קורי וודס, הוא אחד מחברי הוו־טאנג קלאן (אלבום 748), עם קול חד ומהיר וסגנון של מספר סיפורים. Only Built 4 Cuban Linx..., אלבום הסולו הראשון שלו, יצא ב־1995, והופק כולו על ידי RZA, המפיק של הקבוצה. בכמעט כל שיר משתתף לצידו חברו גוסטפייס קילה, כך שלמעשה זה אלבום של צמד. הקלטת המקורית יצאה בצבע סגול, ולכן מעריצים קוראים לאלבום עד היום "הקלטת הסגולה".''',
'''האלבום בנוי כמו סרט פשע: ראקוון וגוסטפייס מספרים סיפורים על עולם תחתון דמיוני, עם עסקאות, בגידות, כסף ומלחמות, בהשראת סרטי מאפיה כמו "הסנדק" ו"פני צלקת", ועם קטעי דיאלוג קצרים בין השירים. הקצבים של RZA קולנועיים, עם כלי מיתר, פסנתר ודגימות של סול, והראפ צפוף, מהיר ומלא בסלנג ובשמות קוד. Ice Cream הוא שיר שובב ומצחיק, עם מת׳וד מן וקאפאדונה, על בחורות, עם דגימה רכה של סול. Criminology הוא שיר מהיר ואנרגטי, שנפתח בקטע מתוך "פני צלקת". Incarcerated Scarfaces מהיר ומלא ביטחון, ו־Verbal Intercourse כולל בית של נאס, הראפר הראשון מחוץ לקבוצה שהופיע באלבום שלה. Rainy Dayz נוגה ויפה. המילים עוסקות לא מעט באלימות ובפשע.''',
'''Only Built 4 Cuban Linx... נחשב לאחד מאלבומי ההיפ הופ הגדולים של שנות התשעים, והשפיע מאוד על הסגנון שנקרא מאפיוזו ראפ. הוא ביסס את ראקוון וגוסטפייס כשני הכותבים המבריקים של הקבוצה.''',
'''שמעו את Ice Cream ואחריו את Verbal Intercourse, ואחר כך את Illmatic של נאס (אלבום 762), כדי להכיר את האורח המפורסם של האלבום.''',
], [
('Ice Cream', 'שיר שובב ומצחיק עם מת׳וד מן וקאפאדונה, עם דגימה רכה של סול.'),
('Criminology', 'שיר מהיר ואנרגטי שנפתח בקטע מתוך הסרט "פני צלקת".'),
('Incarcerated Scarfaces', 'שיר מהיר ומלא ביטחון, עם קצב קולנועי וחד של RZA.'),
])

add(790, [
'''אחרי ההצלחה של Siamese Dream (אלבום 735), בילי קורגן רצה לעשות משהו גדול עוד יותר: אלבום כפול, עם עשרים ושמונה שירים, שיתאר יום שלם, מהבוקר ועד הלילה, ואולי גם חיים שלמים. Mellon Collie and the Infinite Sadness יצא ב־1995, בשני תקליטורים שנקראו "שחר עד דמדומים" ו"דמדומים עד אור כוכבים". המפיקים היו פלאד ואלן מולדר, והפעם השתתפו כל חברי הלהקה בנגינה ובכתיבה של חלק מהשירים.''',
'''האלבום מגוון מאוד: רוק כבד ומתפוצץ, פופ רך וחלומי, בלדות עם פסנתר, קטעי מטאל כועסים ושירים אקוסטיים שקטים. Tonight, Tonight הוא שיר גדול ומלא תקווה, עם תזמורת כלי מיתר שלמה, והקליפ שלו, בהשראת סרט אילם ישן על מסע לירח, הפך למפורסם. Bullet with Butterfly Wings הוא שיר כועס ורועש, עם השורה המפורסמת על חולדה בכלוב. 1979 הוא שיר נוסטלגי ויפה על נעורים, עם קצב אלקטרוני רך ומנגינה חמה, אחד השירים האהובים של שנות התשעים. Zero כבד ומאיים, ו־Thirty-Three רך וחלומי. Mellon Collie and the Infinite Sadness, הפותח, הוא קטע פסנתר קצר ויפה.''',
'''האלבום הגיע למקום הראשון במצעד האמריקאי, נמכר במיליוני עותקים, ונחשב לאחד מאלבומי הכפול המצליחים בתולדות הרוק. הוא זכה בפרסי גראמי, והפך את הסמאשינג פאמפקינס לאחת הלהקות הגדולות בעולם. השירים 1979 ו־Tonight, Tonight מושמעים עד היום ברדיו, והם מהשירים המוכרים ביותר של התקופה.''',
'''זה אלבום ארוך מאוד, ואין צורך לשמוע אותו בבת אחת. התחילו מ־Tonight, Tonight ומ־1979, ואחר כך שמעו את Siamese Dream (אלבום 735), כדי להשוות.''',
], [
('Tonight, Tonight', 'שיר גדול ומלא תקווה, עם תזמורת כלי מיתר שלמה וקליפ מפורסם.'),
('1979', 'שיר נוסטלגי ויפה על נעורים, עם קצב אלקטרוני רך ומנגינה חמה.'),
('Bullet with Butterfly Wings', 'שיר כועס ורועש, עם השורה המפורסמת על חולדה בכלוב.'),
])

add(791, [
'''רוקט פרום דה קריפט היו להקה מסן דייגו, שבראשה עמד ג׳ון רייס, המכונה ספידו, שניגן במקביל גם בדרייב לייק ג׳הו (אלבום 770). אבל בעוד שדרייב לייק ג׳הו ניגנו מוזיקה מסובכת ואפלה, רוקט פרום דה קריפט היו מסיבה של רוקנרול: הם הופיעו בבגדים תואמים, עם חצוצרה וסקסופון, ורצו פשוט שהקהל ירקוד. מעריצים שקעקעו את סמל הלהקה קיבלו, כך סופר, כניסה חינם להופעות שלהם לכל החיים. Scream, Dracula, Scream!, שיצא ב־1995, הוא האלבום המצליח והאהוב שלהם.''',
'''הצליל הוא רוקנרול חזק, מהיר ושמח, שמחבר בין פאנק, רוקנרול של שנות החמישים, סול ורוק גראז׳ של שנות השישים: גיטרות רועשות, תופים דוהרים, כלי נשיפה שמנגנים ריפים גדולים, פזמונים שנועדו לשירה של קהל, וספידו שצועק בקול צרוד ומלא אנרגיה. השירים מתחברים זה לזה בלי הפסקה, כמו הופעה אחת ארוכה. On a Rope, הלהיט הגדול, הוא שיר קצבי וסוחף עם מחיאות כפיים ופזמון שקל לשיר, שאפילו נכנס למצעד הבריטי. Born in '69 מהיר וחזק, עם כלי נשיפה, ו־Young Livers הוא שיר רוקנרול מתפוצץ, שלא נותן לרגע של מנוחה. ספידו נראה על הבמה כמו מנחה של מופע ישן, עם תסרוקת גבוהה ובגדים מבריקים, והלהקה שמחה לשחק את התפקיד.''',
'''Scream, Dracula, Scream! נחשב לאחד מאלבומי הרוקנרול הכיפיים של שנות התשעים, והלהקה זכתה בזכותו להצלחה גדולה במיוחד בבריטניה. היא התפרקה באמצע שנות האלפיים, וחזרה להופיע שוב אחרי כעשור, לשמחת המעריצים עם הקעקועים.''',
'''שמעו את On a Rope בווליום גבוה, ואחריו את Yank Crime של דרייב לייק ג׳הו (אלבום 770), ותשמעו כמה שונים שני הצדדים של אותו מוזיקאי.''',
], [
('On a Rope', 'הלהיט, שיר קצבי וסוחף עם מחיאות כפיים ופזמון שקל לשיר.'),
('Born in \'69', 'שיר מהיר וחזק, עם כלי נשיפה וגיטרות רועשות.'),
('Young Livers', 'שיר רוקנרול מתפוצץ, עם קצב דוהר וצעקות של ספידו.'),
])

add(792, [
'''הכמיקל ברדרס הם טום רולנדס ואד סימונס, שני חברים שנפגשו כסטודנטים באוניברסיטת מנצ׳סטר, בעיר שבה סצנת המסיבות הייתה בשיאה. בתחילה קראו לעצמם הדאסט ברדרס, על שם צמד מפיקים אמריקאים שהעריצו, אבל כשהצמד האמריקאי התלונן, הם שינו את השם. הם התפרסמו כתקליטנים במועדון לונדוני קטן, שבו ניגנו היפ הופ, טכנו, רוק ופאנק ערבובים. Exit Planet Dust, אלבום הבכורה שלהם, יצא ב־1995, ושמו מתייחס לשם הקודם שלהם.''',
'''המוזיקה שלהם נקראה ביג ביט: קצבי ברייקביט כבדים ומקפצים, כמו בהיפ הופ, בס עבה, סינתיסייזרים צורמים וגלים של רעש, ודגימות של רוק, פאנק ופסיכדליה. היא נשמעת כמו מוזיקת ריקודים עם אנרגיה של להקת רוק. Leave Home הפותח הוא קטע כבד, מהיר וסוחף, עם קריאה שחוזרת. Chemical Beats הוא קטע ריקוד מתפוצץ, ו־In Dust We Trust מאיים ועוצמתי. בסוף האלבום הצד משתנה, ומגיעים שני שירים עם זמרים: Life Is Sweet, עם טים ברג׳ס מהשרלטנס, הוא שיר ריקוד שמח, ו־Alive Alone, עם בת אורטון, הוא שיר איטי, רך וחלומי. One Too Many Mornings שקט ומרחף.''',
'''Exit Planet Dust הפך את הכמיקל ברדרס לאחת הלהקות החשובות של המוזיקה האלקטרונית, ופתח את הדרך לגל של ביג ביט, שבו מוזיקה אלקטרונית כבשה את קהל הרוק. האלבום הבא שלהם, Dig Your Own Hole, הגיע למקום הראשון במצעד הבריטי.''',
'''שמעו את Leave Home בווליום גבוה, ואחריו את Alive Alone, ותשמעו את שני הצדדים של הצמד. ואחר כך השוו ל־Music for the Jilted Generation (אלבום 783).''',
], [
('Leave Home', 'הפותח, קטע כבד, מהיר וסוחף, עם קריאה שחוזרת ובס עבה.'),
('Life Is Sweet', 'שיר ריקוד שמח, עם קולו של טים ברג׳ס מהשרלטנס.'),
('Alive Alone', 'שיר איטי, רך וחלומי, בקולה העדין של בת אורטון.'),
])

add(793, [
'''טופאק שאקור נולד בניו יורק לאם שהייתה פעילה בתנועת הפנתרים השחורים, וגדל בעוני, בין ניו יורק, בולטימור וקליפורניה. בילדותו למד גם משחק ושירה בבית ספר לאמנויות. הוא התפרסם בתחילת שנות התשעים כראפר וכשחקן, עם דמות מורכבת: מצד אחד משורר רגיש עם מודעות פוליטית, ומצד שני אדם שהסתבך שוב ושוב עם החוק. Me Against the World יצא בתחילת 1995, כשהוא כבר ישב בכלא, והגיע למקום הראשון במצעד האמריקאי.''',
'''זה האלבום האישי והמהורהר ביותר שלו. הקצבים איטיים, חמים ועצובים, עם דגימות של סול ואר אנד בי, כלי מיתר ופסנתר, וטופאק מספר בקול רציני ומלא רגש על פחד, על מוות, על חברים שהלכו, על עוני ועל הרצון לשרוד. Dear Mama הוא שיר תודה מרגש לאמו, אפני שאקור, שמספר בכנות על הקשיים שלה ועל אהבתו אליה, והוא אחד משירי ההיפ הופ האהובים בכל הזמנים. So Many Tears הוא שיר עצוב ושבור על חיים קשים, עם מפוחית. Me Against the World, שיר הנושא, מתאר אדם שמרגיש שכל העולם נגדו. Temptations קליל ושמח יותר, ו־Old School הוא מחווה חמה לראפרים שגדל עליהם.''',
'''Me Against the World נחשב לאחד האלבומים הטובים של טופאק, ו־Dear Mama נבחר אפילו לשימור בספריית הקונגרס האמריקאית. טופאק נרצח ב־1996, בגיל עשרים וחמש בלבד, והפך לאחד הראפרים המשפיעים והמוכרים בתולדות המוזיקה.''',
'''הקשיבו למילים של Dear Mama, ואחריו שמעו את Ready to Die של הנוטוריוס בי.איי.ג׳י. (אלבום 778), עוד אלבום מאותן שנים שעוסק בחיים ובמוות.''',
], [
('Dear Mama', 'שיר תודה מרגש לאמו, אחד משירי ההיפ הופ האהובים בכל הזמנים.'),
('So Many Tears', 'שיר עצוב ושבור על חיים קשים, עם מפוחית וקצב איטי.'),
('Me Against the World', 'שיר הנושא, על אדם שמרגיש שכל העולם עומד נגדו.'),
])

add(794, [
'''אלסטיקה קמו בלונדון בתחילת שנות התשעים, סביב הזמרת והגיטריסטית ג׳סטין פרישמן, שהייתה בעבר חברה בגרסה המוקדמת של סוויד (אלבום 733), לצד הגיטריסטית דונה מת׳יוז, הבסיסטית אנני הולנד והמתופף ג׳סטין וולש. הם אהבו את הפאנק והפוסט־פאנק של סוף שנות השבעים, ובמיוחד את ווייר ואת הסטרנגלרס. אלבום הבכורה שלהם, שנושא את שם הלהקה, יצא ב־1995, ובזמנו היה אחד מאלבומי הבכורה שנמכרו הכי מהר בתולדות בריטניה.''',
'''השירים קצרים, חדים ומהירים, רובם שתיים או שלוש דקות: גיטרות פשוטות ועוקצניות, בס ישיר, תופים יבשים, ופרישמן ששרה בקול קר, אדיש ומלא ביטחון, על סקס, על מכוניות, על מסיבות ועל גברים. הכל נשמע מגניב, ישיר ובלי מאמץ, בדיוק כמו להקות הפאנק שהם אהבו. Connection, הלהיט הגדול, נבנה על ריף קצר ומקפץ. Waking Up הוא שיר שמח וקליט על העצלות של הבוקר. Stutter, הסינגל הראשון, מהיר ועוקצני. Car Song הוא שיר חושני ומצחיק על אהבה במכונית, ו־Line Up הוא שיר לגלגני על בחורות שמנסות להתקרב לכוכבים. האלבום כולו עובר במהירות, כמו מסיבה קצרה ורועשת, ומשאיר את המאזינים עם רצון לשמוע אותו שוב.''',
'''הדמיון לשירים ישנים לא נעלם מעין: Connection הזכיר מאוד שיר של ווייר, ו־Waking Up הזכיר שיר של הסטרנגלרס, והלהקה הגיעה עם הכותבים להסדר מחוץ לבית המשפט. האלבום הצליח מאוד גם בארצות הברית, אבל הלהקה התקשתה להמשיך, והוציאה רק עוד אלבום אחד.''',
'''שמעו את Connection, ואחריו את Pink Flag של ווייר (אלבום 379), ונסו לגלות בעצמכם מאיזה שיר הגיע הריף.''',
], [
('Connection', 'הלהיט, שיר קצר וחד, שנבנה על ריף קטן ומקפץ.'),
('Waking Up', 'שיר שמח וקליט על העצלות של הבוקר, עם פזמון גדול.'),
('Stutter', 'הסינגל הראשון, שיר קצר מאוד, מהיר ועוקצני ומלא אנרגיה.'),
])

add(795, [
'''סופרגראס קמו באוקספורד בתחילת שנות התשעים, סביב גז קומבס, זמר וגיטריסט עם פאות לחיים גדולות, שהיה רק בן תשע עשרה כשהאלבום יצא, המתופף דני גופי והבסיסט מיק קווין. הם היו צעירים, שובבים ומלאי אנרגיה, ואהבו את הרוקנרול של שנות השישים והשבעים, מהקינקס ועד באזקוקס. I Should Coco, אלבום הבכורה שלהם, יצא ב־1995, בשיא הבריטפופ, והגיע למקום הראשון במצעד הבריטי. השם הוא ביטוי סלנג קוקני, שפירושו "בטח, ברור".''',
'''המוזיקה מהירה, שמחה וקופצנית: גיטרות חזקות, פסנתר מקפץ, תופים מהירים, הרמוניות קוליות ופזמונים קליטים, עם הרבה הומור והרבה שטויות של בני נוער. Alright, הלהיט הגדול, הוא שיר שמח ומלא שמש על הכיף של להיות צעיר, עם פסנתר מקפץ, שהפך להמנון של קיץ 1995. Caught by the Fuzz, הסינגל הראשון, הוא שיר פאנק מהיר ומצחיק על נער שנעצר בידי המשטרה ואמו מגיעה לתחנה. Mansize Rooster הוא שיר רוקנרול שובב, עם פסנתר בסגנון של פעם. Lenny ו־Strange Ones רועשים ומהירים, ו־Time נוגה ואיטי יותר, ומראה צד רגוע של הלהקה.''',
'''I Should Coco נמכר היטב, והפך את סופרגראס לאחת הלהקות האהובות של הבריטפופ. הם המשיכו להוציא אלבומים בוגרים ומגוונים יותר במשך יותר מעשור, והתאחדו מחדש להופעות שנים אחרי שהתפרקו. הם נודעו גם בקליפים המצחיקים שלהם, שבהם רכבו על אופניים ושיחקו כמו ילדים גדולים.''',
'''זה אלבום לבוקר קיץ, לנסיעה או למסיבה. שמעו את Alright ואת Caught by the Fuzz, ואחר כך שמעו את Parklife של בלר (אלבום 771), עוד אלבום שמח ובריטי מאותן שנים.''',
], [
('Alright', 'הלהיט, שיר שמח ומלא שמש על הכיף של להיות צעיר, עם פסנתר מקפץ.'),
('Caught by the Fuzz', 'שיר פאנק מהיר ומצחיק על נער שנעצר בידי המשטרה.'),
('Mansize Rooster', 'שיר רוקנרול שובב עם פסנתר בסגנון של פעם ופזמון קליט.'),
])

add(796, [
'''רדיוהד מאוקספורד התפרסמו ב־1993 בזכות להיט אחד, Creep, ששר על נער שמרגיש לא שייך, וחשש גדול ריחף מעליהם שהם יישארו "להקה של שיר אחד". The Bends, האלבום השני שלהם, שיצא ב־1995 בהפקת ג׳ון לקי, הוכיח את ההפך. תום יורק, הזמר, יחד עם האחים ג׳וני וקולין גרינווד, אד אובריאן ופיל סלווי, כתבו כאן שירים עמוקים, יפים ומגוונים, שהפכו אותם לאחת הלהקות החשובות של זמנם.''',
'''הצליל מחבר בין גיטרות רוק חזקות לבין רגעים שקטים, אקוסטיים ומלנכוליים. שלוש הגיטרות של הלהקה בונות שכבות עשירות של צליל, וקולו של יורק, גבוה, שביר ומלא רגש, עוסק בניכור, בטכנולוגיה, בחולי ובבדידות. Fake Plastic Trees הוא שיר עצוב ויפה על עולם מלאכותי ועל אהבה, שמתחיל בגיטרה אקוסטית ונבנה לאט. לפי הסיפור, יורק הקליט את השירה בטייק אחד, אחרי שראה הופעה של ג׳ף באקלי (אלבום 779). Street Spirit (Fade Out), הסוגר, הוא שיר אפל ומהפנט, עם גיטרה מסתלסלת. Just הוא שיר רוק מהיר ומלא בגיטרות מטורפות, ו־High and Dry רך ונוגה. My Iron Lung כועס ורועש. השירים נעים בין רעש גדול לשקט עדין, ויוצרים אלבום שלם ומגובש, בלי רגע אחד מיותר.''',
'''The Bends נמכר היטב, ומוזיקאים רבים, בבריטניה ובעולם, ראו בו השראה. האלבום הבא, OK Computer, הפך את רדיוהד לאחת הלהקות הגדולות והמשפיעות בעולם, אבל רבים חושבים שהכל התחיל כאן.''',
'''שמעו את Fake Plastic Trees ואחריו את Grace של ג׳ף באקלי (אלבום 779), ותשמעו את ההשפעה. ואחר כך שמעו את Street Spirit (Fade Out) בחושך.''',
], [
('Fake Plastic Trees', 'שיר עצוב ויפה על עולם מלאכותי, שמתחיל בגיטרה אקוסטית ונבנה לאט.'),
('Street Spirit (Fade Out)', 'הסוגר, שיר אפל ומהפנט, עם גיטרה מסתלסלת וקול שבור.'),
('Just', 'שיר רוק מהיר ומלא בגיטרות מטורפות ובפזמון שקשה לשכוח.'),
])

add(797, [
'''גאיידד ביי וויסס היא להקה מדייטון שבאוהיו, שבראשה עומד רוברט פולארד, מורה בבית ספר יסודי, שכתב מאות שירים והקליט אותם בבית עם חברים, על מכשיר הקלטה פשוט של ארבעה ערוצים. במשך יותר מעשור כמעט איש מחוץ לעיר לא שמע עליהם, והם הוציאו את התקליטים בעצמם, במהדורות קטנות. רק בתחילת שנות התשעים התחילו מבקרים ומוזיקאים לגלות אותם, ופולארד עזב את ההוראה. Alien Lanes, שיצא ב־1995, היה האלבום הראשון שלהם בחברת התקליטים מטאדור.''',
'''באלבום עשרים ושמונה שירים, בתוך כארבעים ואחת דקות בלבד. רוב השירים קצרים מאוד, דקה או שתיים, ולפעמים אפילו פחות, כאילו פולארד שופך רעיונות בלי לעצור. ההקלטה ביתית ורועשת, עם רחש של קלטת וגיטרות מלוכלכות, אבל מתחתיה מסתתרות מנגינות פופ נהדרות, בהשראת הביטלס ולהקת ה־Who, ופזמונים שנתקעים בראש. Game of Pricks הוא שיר רוק קצר ומושלם, עם פזמון גדול ועצוב, אולי השיר המפורסם שלהם. Motor Away הוא שיר מהיר ומלא תקווה על בריחה במכונית. My Valuable Hunting Knife קליט ומצחיק, ו־Watch Me Jumpstart רועש ושמח. כמה שירים כתב ושר חבר הלהקה טוביאס ספראוט, והם רכים ושקטים יותר. יש באלבום תחושה של מחברת סקיצות פתוחה, שבה כל רעיון מקבל דקה אחת של חיים.''',
'''Alien Lanes הוא אחד האלבומים החשובים של הלו־פיי האמריקאי, יחד עם אלבומי סבאדו (אלבום 752) ופייבמנט. פולארד המשיך לכתוב ולהקליט בקצב מדהים, ועד היום הוציא, עם הלהקה ובלעדיה, יותר ממאה אלבומים.''',
'''אל תחפשו כאן שירים ארוכים. שמעו את האלבום ברצף, כמו רדיו שעובר בין תחנות, ושימו לב לפזמונים שמופיעים ונעלמים. התחילו מ־Game of Pricks.''',
], [
('Game of Pricks', 'שיר רוק קצר ומושלם, עם פזמון גדול ועצוב, אולי המפורסם שלהם.'),
('Motor Away', 'שיר מהיר ומלא תקווה על בריחה במכונית, עם גיטרות רועשות.'),
('My Valuable Hunting Knife', 'שיר קליט ומצחיק, עם מנגינה פשוטה ושירה שמחה.'),
])

add(799, [
'''הוורב קמו בוויגן, עיירה ליד מנצ׳סטר, בתחילת שנות התשעים, סביב הזמר ריצ׳רד אשקרופט, עם קול חזק ונוכחות כריזמטית, והגיטריסט ניק מקייב, שהיה מסוגל לבנות מהגיטרה עולמות שלמים של צליל. האלבום הראשון שלהם היה פסיכדלי וחלומי, ול־A Northern Soul, שיצא ב־1995, הם הביאו את המפיק אוון מוריס, שעבד עם אואזיס. ההקלטות, שנערכו בעיקר בוויילס, היו כאוטיות וסוערות, והיחסים בלהקה הידרדרו מאוד.''',
'''האלבום חזק, רחב ומלא רגש: גיטרות ענקיות ומהדהדות של מקייב, בס עמוק, תופים חזקים, וקולו של אשקרופט, שעובר מלחישה לצעקה ומשמחה לייאוש. השירים ארוכים, חלקם יותר משש דקות, ומלאים בקטעים מאולתרים, פסיכדליים ורועשים. History הוא שיר גדול ועצוב, עם תזמורת כלי מיתר, על אהבה שנגמרה, שנפתח במילים בהשראת שיר של המשורר ויליאם בלייק. On Your Own הוא שיר אקוסטי שקט ויפה על בדידות, ו־This Is Music הוא שיר רוק חזק ובטוח בעצמו. A New Decade, הפותח, מתפרץ בעוצמה, ו־So It Goes ארוך ומהפנט.''',
'''זמן קצר אחרי צאת האלבום הלהקה התפרקה, אבל חזרה כעבור כשנתיים עם Urban Hymns ועם Bitter Sweet Symphony, שהפכו אותה לתופעה עולמית. נואל גלאגר מאואזיס, חבר של אשקרופט, הקדיש לו את השיר Cast No Shadow. רבים רואים ב־A Northern Soul את הגשר בין הצליל הפסיכדלי של ההתחלה לבין ההצלחה הגדולה שבאה אחר כך.''',
'''שמעו את History באוזניות, ושימו לב לכלי המיתר ולקול של אשקרופט. ואחר כך שמעו את Definitely Maybe של אואזיס (אלבום 767), שגם בו עבד אוון מוריס, באותה תקופה.''',
], [
('History', 'שיר גדול ועצוב עם תזמורת כלי מיתר, על אהבה שנגמרה.'),
('On Your Own', 'שיר אקוסטי שקט ויפה על בדידות, בקול רך ומלא כאב.'),
('This Is Music', 'שיר רוק חזק ובטוח בעצמו, עם גיטרות ענקיות ומהדהדות.'),
])

add(800, [
'''ג׳יזה, המכונה גם ג׳יניוס, גרי גרייס, הוא בן דודו של RZA, והחבר המבוגר ביותר בוו־טאנג קלאן (אלבום 748). הוא היה הראשון מהקבוצה שהוציא אלבום, עוד ב־1991, בחברת תקליטים שלא ידעה מה לעשות איתו, והאלבום נכשל. אחרי ההצלחה של הקבוצה הוא קיבל הזדמנות שנייה, ו־Liquid Swords, שיצא בסוף 1995, הופק כולו על ידי RZA. רבים רואים בו את אלבום הסולו הטוב ביותר של חברי הקבוצה.''',
'''הצליל אפל, קר ומינימלי: קצבים איטיים וכבדים, פסנתרים מאיימים, כלי מיתר מעוותים ודגימות קודרות. האלבום נפתח ומתובל בקטעי דיאלוג מתוך סרט סמוראים יפני ישן, על לוחם עם חרב וילד, שנותנים לו תחושה של סרט אפל ומתוח. ג׳יזה ראפ בקול שקט, קר ומחושב, כמו שחקן שחמט, עם מילים מדויקות, חכמות ומלאות בדימויים, והוא נחשב לאחד הכותבים הטובים בהיפ הופ. Liquid Swords, שיר הנושא, הוא שיר קר ומהפנט, עם פזמון שחוזר. Labels הוא שיר מבריק, שבו ג׳יזה בונה סיפור שלם משמות של חברות תקליטים. Shadowboxin', עם מת׳וד מן, מהיר וחד. Cold World קודר וכבד, ו־4th Chamber מביא כמה מחברי הקבוצה לקרב ראפ מהיר.''',
'''Liquid Swords נחשב לאחד מאלבומי ההיפ הופ הגדולים של שנות התשעים. העטיפה, ציור בסגנון קומיקס של לוח שחמט עם לוחמים, הפכה למפורסמת, ושחמט הפך לחלק מהדימוי של ג׳יזה, שהמשיך לכתוב ולהופיע במשך שנים.''',
'''הקשיבו כאן למילים, והתחילו מ־Labels. ואחר כך שמעו את Only Built 4 Cuban Linx... של ראקוון (אלבום 789), מאותה שנה ומאותה קבוצה, בסגנון שונה לגמרי.''',
], [
('Liquid Swords', 'שיר הנושא, קר ומהפנט, עם פזמון שחוזר וקטע מתוך סרט סמוראים.'),
('Labels', 'שיר מבריק, שבו ג׳יזה בונה סיפור שלם משמות של חברות תקליטים.'),
('Shadowboxin\'', 'שיר מהיר וחד עם מת׳וד מן, עם קצב כבד ופסנתר מאיים.'),
])

add(754, [
'''ויליאם אורביט, ששמו האמיתי ויליאם וויינרייט, הוא מפיק ומוזיקאי לונדוני, שהתחיל בשנות השמונים בלהקת פופ אלקטרוני בשם טורץ׳ סונג, ועבד כמפיק וכרמיקסר לאמנים רבים. במקביל, הוא הוציא סדרה של אלבומים אינסטרומנטליים בשם Strange Cargo, "מטען מוזר", שבהם חקר צלילים אלקטרוניים רכים ואווירתיים. Strange Cargo III, האלבום השלישי בסדרה, יצא ב־1993, והוא אולי היפה והמגובש מכולם, אלבום שבו המוזיקה האלקטרונית נשמעת חמה ואנושית.''',
'''המוזיקה רגועה, חלומית ומלאה אוויר: סינתיסייזרים רכים, גיטרות מהדהדות, קצבים איטיים של היפ הופ ודאב, בס עמוק, וצלילים קטנים שנעים מאוזן לאוזן. רוב הקטעים בלי מילים, ונשמעים כמו פסקול לנסיעה בלילה או לשקיעה ליד הים. Water from a Vine Leaf הוא הקטע המפורסם באלבום, עם קולה של הזמרת הצעירה בת אורטון, שהייתה אז כמעט לא מוכרת, והוא שיר יפה, רך ומרחף. Time to Get Wize קצבי ומקפץ יותר, ו־A Hazy Shade of Random מתנדנד ועצל. The Story of Light ו־Harry Flowers שקטים ויפים, ו־Water Babies, הסוגר, רגוע ומרגיע.''',
'''האלבום לא הפך ללהיט גדול, אבל הוא נחשב לאחד מאלבומי הצ׳יל אאוט הבריטיים החשובים של התקופה. כמה שנים אחר כך הפיק אורביט את Ray of Light של מדונה, שזכה בפרסי גראמי והפך אותו לאחד המפיקים המבוקשים בעולם, ועבד גם עם בלר ועם אול סיינטס. בת אורטון, שהתגלתה כאן, הפכה לזמרת מוכרת ומוערכת בעצמה, ושיתפה פעולה עם אמנים רבים.''',
'''זה אלבום לרקע של ערב רגוע, לקריאה או לנסיעה. שמעו את Water from a Vine Leaf, ואחריו את Selected Ambient Works 85–92 של אייפקס טווין (אלבום 708), עוד צד של אותה מוזיקה אלקטרונית רכה.''',
], [
('Water from a Vine Leaf', 'שיר יפה, רך ומרחף, עם קולה של בת אורטון הצעירה.'),
('Time to Get Wize', 'קטע קצבי ומקפץ, עם בס עמוק וסינתיסייזרים שמחים.'),
('A Hazy Shade of Random', 'קטע מתנדנד ועצל, עם גיטרה מהדהדת וקצב איטי.'),
])

add(798, [
'''פמי קוטי הוא בנו הבכור של פלה קוטי, אבי האפרוביט, שכבר פגשנו באתר (אלבום 232). הוא גדל בלאגוס, בבית מלא מוזיקה ופוליטיקה, והצטרף כנער ללהקה של אביו כנגן סקסופון. באמצע שנות השמונים עזב והקים להקה משלו, פוזיטיב פורס, כדי למצוא את הדרך שלו, צעד שלא היה קל לבן של אדם כה מפורסם וכה דומיננטי. Femi Kuti, האלבום שנושא את שמו, יצא ב־1995, והיה מהראשונים שלו שהגיעו לקהל בינלאומי רחב.''',
'''המוזיקה היא אפרוביט, הסגנון שהמציא אביו: קצבים מתגלגלים של תופים וכלי הקשה, בס עמוק וגמיש, גיטרות קצרות שחוזרות על עצמן, עוגב, וכלי נשיפה חזקים שמנגנים ריפים גדולים יחד, עם סולואים של סקסופון. אבל בעוד שפלה כתב יצירות של עשרים דקות ויותר, השירים של פמי קצרים, מהירים וממוקדים יותר, כמעט שירי פופ, עם אנרגיה של להקת פאנק. המילים, באנגלית ובפידג׳ין, עוסקות בשחיתות, בעוני, בכוח ובקשיים של החיים בניגריה, ממשיכות את המחאה של אביו בקול משלו. Wonder Wonder הפותח קצבי וסוחף, עם כלי נשיפה חזקים. Survival קצבי ועוצמתי, ו־Changes מהיר וסוחף, עם כלי נשיפה שלא נחים לרגע.''',
'''האלבום הציג את פמי לעולם כמוזיקאי בזכות עצמו, והוא המשיך לקריירה בינלאומית ארוכה, עם הופעות בכל העולם ומועמדויות לפרסי גראמי. גם בנו, מאדה קוטי, מנגן היום אפרוביט, וממשיך את מסורת המשפחה.''',
'''שמעו את Wonder Wonder, ואחריו את Live! של פלה קוטי (אלבום 232), ושימו לב איך הבן קיצר, האיץ וחידד את המוזיקה של האב.''',
], [
('Wonder Wonder', 'הפותח, אפרוביט קצבי וסוחף, עם כלי נשיפה חזקים ותופים מתגלגלים.'),
('Survival', 'שיר קצבי ועוצמתי, עם בס עמוק, עוגב וסקסופון חם.'),
('Changes', 'שיר מהיר וסוחף, עם כלי נשיפה שלא נחים ותופים דוהרים.'),
])
